/* The Grounded Readings Library, group cath (GWG BLD 798). Written by build-readings.py; edit the data, then build again. */
(window.GGReadingsData = window.GGReadingsData || {})["cath"] = [{"id":"cath-sign-of-the-cross","title":"The Sign of the Cross","by":"Traditional","year":1888,"trad":["catholic"],"denom":["rosary"],"type":"prayer","occasion":["daily","blessing"],"text":"In the name of the Father, and of the Son, and of the Holy Ghost. Amen.","translit":"In nomine Patris, et Filii, et Spiritus Sancti. Amen.","note":"Said while tracing the cross on the body, to open and close every prayer and the Rosary.","voice":"jenny","source":{"name":"A Manual of Prayers for the Use of the Catholic Laity (1888), Internet Archive","url":"https://archive.org/search?query=%22Manual+of+Prayers+for+the+Use+of+the+Catholic+Laity%22"},"rights":"pd","pd":"Traditional prayer; this English form was in Catholic prayer books by the 1800s; public domain."},{"id":"cath-apostles-creed","title":"The Apostles' Creed","by":"Traditional","year":1891,"trad":["catholic","christian"],"denom":["rosary"],"type":"prayer","occasion":["daily"],"text":"I believe in God, the Father Almighty, Creator of heaven and earth;\nand in Jesus Christ, His only Son, our Lord;\nwho was conceived by the Holy Ghost, born of the Virgin Mary,\nsuffered under Pontius Pilate, was crucified, died, and was buried.\nHe descended into hell; the third day He arose again from the dead;\nHe ascended into heaven, sitteth at the right hand of God, the Father Almighty;\nfrom thence He shall come to judge the living and the dead.\n\nI believe in the Holy Ghost, the holy Catholic Church, the communion of saints,\nthe forgiveness of sins, the resurrection of the body, and life everlasting. Amen.","translit":"Credo in Deum, Patrem omnipotentem","note":"Prayed on the crucifix at the start of the Rosary, and a statement of faith for any gathering.","voice":"brian","source":{"name":"Baltimore Catechism (1891), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/search/?query=baltimore+catechism"},"rights":"pd","pd":"Ancient creed; this English form is from the Baltimore Catechism, 1891; public domain."},{"id":"cath-our-father","title":"The Our Father","by":"Traditional","year":1891,"trad":["catholic"],"denom":["rosary"],"type":"prayer","occasion":["daily","comfort"],"text":"Our Father, who art in heaven, hallowed be Thy name;\nThy kingdom come; Thy will be done on earth as it is in heaven.\nGive us this day our daily bread;\nand forgive us our trespasses, as we forgive those who trespass against us;\nand lead us not into temptation, but deliver us from evil. Amen.","translit":"Pater noster, qui es in caelis","note":"The Lord's Prayer in its Catholic form, prayed on each large bead of the Rosary.","voice":"jenny","source":{"name":"Baltimore Catechism (1891), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/search/?query=baltimore+catechism"},"rights":"pd","pd":"Matthew 6:9 to 13; this Catholic English form is from the Baltimore Catechism, 1891; public domain."},{"id":"cath-hail-mary","title":"The Hail Mary","by":"Traditional","year":1891,"trad":["catholic"],"denom":["rosary"],"type":"prayer","occasion":["daily","dying","comfort"],"text":"Hail Mary, full of grace, the Lord is with thee;\nblessed art thou among women,\nand blessed is the fruit of thy womb, Jesus.\n\nHoly Mary, Mother of God,\npray for us sinners,\nnow and at the hour of our death. Amen.","translit":"Ave Maria, gratia plena, Dominus tecum","note":"Prayed on each of the ten small beads of a Rosary decade, and often at a bedside in the last hours.","voice":"brian","source":{"name":"Baltimore Catechism (1891), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/search/?query=baltimore+catechism"},"rights":"pd","pd":"Luke 1:28 and 1:42 with the traditional closing; this English form is from the Baltimore Catechism, 1891; public domain."},{"id":"cath-glory-be","title":"The Glory Be","by":"Traditional","year":1891,"trad":["catholic","christian"],"denom":["rosary"],"type":"prayer","occasion":["daily","gratitude"],"text":"Glory be to the Father, and to the Son, and to the Holy Ghost.\nAs it was in the beginning, is now, and ever shall be, world without end. Amen.","translit":"Gloria Patri, et Filio, et Spiritui Sancto","note":"Closes each decade of the Rosary and many other prayers, a short song of praise.","voice":"jenny","source":{"name":"Baltimore Catechism (1891), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/search/?query=baltimore+catechism"},"rights":"pd","pd":"Ancient doxology; this English form is from the Baltimore Catechism, 1891; public domain."},{"id":"cath-fatima-prayer","title":"The Fatima Prayer","by":"Traditional","year":1917,"trad":["catholic"],"denom":["rosary"],"type":"prayer","occasion":["daily","forgiveness"],"text":"O my Jesus, forgive us our sins,\nsave us from the fires of hell;\nlead all souls to heaven,\nespecially those most in need of Thy mercy.","note":"Many families add it after the Glory Be at the end of each Rosary decade.","voice":"brian","source":{"name":"Fatima Prayer (1917), Wikipedia overview with history","url":"https://en.wikipedia.org/wiki/Fatima_Prayers"},"rights":"pd","pd":"Prayer from Fatima, Portugal, 1917; anonymous traditional English in common use; confirm an early printed English source."},{"id":"cath-hail-holy-queen","title":"Hail, Holy Queen","by":"Traditional","year":1888,"trad":["catholic"],"denom":["rosary"],"type":"prayer","occasion":["comfort","grief","evening"],"text":"Hail, holy Queen, Mother of mercy,\nour life, our sweetness, and our hope.\nTo thee do we cry, poor banished children of Eve;\nto thee do we send up our sighs, mourning and weeping in this valley of tears.\nTurn then, most gracious Advocate, thine eyes of mercy toward us;\nand after this our exile show unto us the blessed fruit of thy womb, Jesus.\nO clement, O loving, O sweet Virgin Mary.\n\nV. Pray for us, O holy Mother of God.\nR. That we may be made worthy of the promises of Christ.","translit":"Salve, Regina, Mater misericordiae","note":"Prayed at the close of the Rosary, and sung at night prayer and at many Catholic funerals.","voice":"jenny","source":{"name":"A Manual of Prayers for the Use of the Catholic Laity (1888), Internet Archive","url":"https://archive.org/search?query=%22Manual+of+Prayers+for+the+Use+of+the+Catholic+Laity%22"},"rights":"pd","pd":"The Salve Regina, eleventh century; this English form was in Catholic prayer books by the 1800s; public domain."},{"id":"cath-rosary-closing-prayer","title":"The Rosary Prayer","by":"Traditional","year":1888,"trad":["catholic"],"denom":["rosary"],"type":"prayer","occasion":["daily"],"text":"Let us pray.\nO God, whose only begotten Son, by His life, death, and resurrection,\nhas purchased for us the rewards of eternal life;\ngrant, we beseech Thee, that meditating upon these mysteries\nof the most holy Rosary of the Blessed Virgin Mary,\nwe may imitate what they contain, and obtain what they promise,\nthrough the same Christ our Lord. Amen.","note":"The closing prayer of the Rosary, after the Hail, Holy Queen.","voice":"brian","source":{"name":"A Manual of Prayers for the Use of the Catholic Laity (1888), Internet Archive","url":"https://archive.org/search?query=%22Manual+of+Prayers+for+the+Use+of+the+Catholic+Laity%22"},"rights":"pd","pd":"Collect from the Roman Missal, Feast of the Holy Rosary; this English form was in prayer books by the 1800s; public domain."},{"id":"cath-how-to-pray-the-rosary","title":"How to Pray the Rosary","by":"Grow With Grounded","year":2026,"trad":["catholic"],"denom":["rosary"],"type":"reflection","occasion":["daily","dying","comfort"],"text":"Hold the crucifix, make the Sign of the Cross, and pray the Apostles' Creed.\nOn the first large bead, pray the Our Father.\nOn the next three beads, pray three Hail Marys, for faith, hope, and love.\nThen pray the Glory Be.\n\nName the first mystery and picture it.\nOn the large bead, pray the Our Father.\nOn the ten small beads, pray ten Hail Marys, resting with the mystery.\nClose the decade with the Glory Be, and the Fatima Prayer if your family prays it.\nPray all five decades the same way.\n\nClose with the Hail, Holy Queen, the Rosary Prayer, and the Sign of the Cross.\n\nThe Joyful Mysteries are prayed on Monday and Saturday, the Sorrowful on Tuesday and Friday, the Glorious on Wednesday and Sunday, and the Luminous on Thursday.\n\nAt a bedside, one decade prayed slowly is a whole and loving prayer. A familiar voice and the soft click of the beads bring peace, even while the one you love rests with eyes closed.","note":"A simple guide for a family or a guide praying the Rosary together, at home or at a bedside.","voice":"jenny","source":{"name":"Grow With Grounded, written for the Grounded Readings Library (2026)","url":""},"rights":"grounded","pd":"Grounded's own words."},{"id":"cath-mystery-joyful-1-annunciation","title":"The First Joyful Mystery: The Annunciation","by":"Douay-Rheims Bible, Luke 1:28, 30 to 31, 38","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["birth","hope"],"text":"And the angel being come in, said unto her: Hail, full of grace, the Lord is with thee: blessed art thou among women.\n\nAnd the angel said to her: Fear not, Mary, for thou hast found grace with God.\nBehold thou shalt conceive in thy womb and shalt bring forth a son: and thou shalt call his name Jesus.\n\nAnd Mary said: Behold the handmaid of the Lord: be it done to me according to thy word. And the angel departed from her.","note":"Read aloud before its decade of the Rosary, to give the mind a picture while the beads are prayed.","voice":"brian","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-mystery-joyful-2-visitation","title":"The Second Joyful Mystery: The Visitation","by":"Douay-Rheims Bible, Luke 1:41 to 42, 46 to 47","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["birth","celebration"],"text":"And it came to pass that when Elizabeth heard the salutation of Mary, the infant leaped in her womb. And Elizabeth was filled with the Holy Ghost.\nAnd she cried out with a loud voice and said: Blessed art thou among women and blessed is the fruit of thy womb.\n\nAnd Mary said: My soul doth magnify the Lord.\nAnd my spirit hath rejoiced in God my Saviour.","note":"Read aloud before its decade of the Rosary, to give the mind a picture while the beads are prayed.","voice":"jenny","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-mystery-joyful-3-nativity","title":"The Third Joyful Mystery: The Nativity","by":"Douay-Rheims Bible, Luke 2:7, 10 to 11","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["birth","season","celebration"],"text":"And she brought forth her first born son and wrapped him up in swaddling clothes and laid him in a manger: because there was no room for them in the inn.\n\nAnd the angel said to them: Fear not; for, behold, I bring you good tidings of great joy that shall be to all the people:\nFor, this day is born to you a Saviour, who is Christ the Lord, in the city of David.","note":"Read aloud before its decade of the Rosary, to give the mind a picture while the beads are prayed.","voice":"brian","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-mystery-joyful-4-presentation","title":"The Fourth Joyful Mystery: The Presentation in the Temple","by":"Douay-Rheims Bible, Luke 2:22, 28 to 30","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["birth","blessing","dying"],"text":"And after the days of her purification, according to the law of Moses, were accomplished, they carried him to Jerusalem, to present him to the Lord:\n\nHe also took him into his arms and blessed God and said\nNow thou dost dismiss thy servant, O Lord, according to thy word in peace:\nBecause my eyes have seen thy salvation,","note":"Read aloud before its decade of the Rosary, to give the mind a picture while the beads are prayed.","voice":"jenny","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-mystery-joyful-5-finding","title":"The Fifth Joyful Mystery: The Finding in the Temple","by":"Douay-Rheims Bible, Luke 2:46, 49, 51","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["home","daily"],"text":"And it came to pass, that, after three days, they found him in the temple, sitting in the midst of the doctors, hearing them and asking them questions.\n\nAnd he said to them: How is it that you sought me? Did you not know that I must be about my father's business?\n\nAnd he went down with them and came to Nazareth and was subject to them. And his mother kept all these words in her heart.","note":"Read aloud before its decade of the Rosary, to give the mind a picture while the beads are prayed.","voice":"brian","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-mystery-luminous-1-baptism","title":"The First Luminous Mystery: The Baptism of the Lord","by":"Douay-Rheims Bible, Matthew 3:16 to 17","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["blessing","birth"],"text":"And Jesus being baptized, forthwith came out of the water: and lo, the heavens were opened to him: and he saw the Spirit of God descending as a dove, and coming upon him.\nAnd behold a voice from heaven saying: This is my beloved Son, in whom I am well pleased.","note":"One of the Luminous Mysteries, named by Saint John Paul II in 2002, read aloud before its decade of the Rosary.","voice":"jenny","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain. The mystery title is a plain name of a Gospel event."},{"id":"cath-mystery-luminous-2-cana","title":"The Second Luminous Mystery: The Wedding at Cana","by":"Douay-Rheims Bible, John 2:1 to 2, 5, 11","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["wedding","celebration"],"text":"And the third day, there was a marriage in Cana of Galilee: and the mother of Jesus was there.\nAnd Jesus also was invited, and his disciples, to the marriage.\n\nHis mother saith to the waiters: Whatsoever he shall say to you, do ye.\n\nThis beginning of miracles did Jesus in Cana of Galilee and manifested his glory. And his disciples believed in him.","note":"One of the Luminous Mysteries, named by Saint John Paul II in 2002, read aloud before its decade of the Rosary.","voice":"brian","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain. The mystery title is a plain name of a Gospel event."},{"id":"cath-mystery-luminous-3-kingdom","title":"The Third Luminous Mystery: The Proclamation of the Kingdom","by":"Douay-Rheims Bible, Mark 1:14 to 15","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["hope","forgiveness"],"text":"And after that John was delivered up, Jesus came in Galilee, preaching the gospel of the kingdom of God,\nAnd saying: The time is accomplished and the kingdom of God is at hand. Repent and believe the gospel:","note":"One of the Luminous Mysteries, named by Saint John Paul II in 2002, read aloud before its decade of the Rosary.","voice":"jenny","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain. The mystery title is a plain name of a Gospel event."},{"id":"cath-mystery-luminous-4-transfiguration","title":"The Fourth Luminous Mystery: The Transfiguration","by":"Douay-Rheims Bible, Matthew 17:1 to 2, 5","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["hope","nature"],"text":"And after six days Jesus taketh unto him Peter and James, and John his brother, and bringeth them up into a high mountain apart:\nAnd he was transfigured before them. And his face did shine as the sun: and his garments became white as snow.\n\nAnd as he was yet speaking, behold a bright cloud overshadowed them. And lo a voice out of the cloud, saying: This is my beloved Son, in whom I am well pleased: hear ye him.","note":"One of the Luminous Mysteries, named by Saint John Paul II in 2002, read aloud before its decade of the Rosary.","voice":"brian","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain. The mystery title is a plain name of a Gospel event."},{"id":"cath-mystery-luminous-5-eucharist","title":"The Fifth Luminous Mystery: The Institution of the Eucharist","by":"Douay-Rheims Bible, Luke 22:19 and John 6:51","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["daily","gratitude"],"text":"And taking bread, he gave thanks and brake and gave to them, saying: This is my body, which is given for you. Do this for a commemoration of me.\n\nI am the living bread which came down from heaven.","note":"One of the Luminous Mysteries, named by Saint John Paul II in 2002, read aloud before its decade of the Rosary.","voice":"jenny","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain. The mystery title is a plain name of a Gospel event."},{"id":"cath-mystery-sorrowful-1-agony","title":"The First Sorrowful Mystery: The Agony in the Garden","by":"Douay-Rheims Bible, Luke 22:41 to 43","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["dying","comfort","grief"],"text":"And he was withdrawn away from them a stone's cast. And kneeling down, he prayed.\nSaying: Father, if thou wilt, remove this chalice from me: but yet not my will, but thine be done.\nAnd there appeared to him an angel from heaven, strengthening him. And being in an agony, he prayed the longer.","note":"Read aloud before its decade of the Rosary, to give the mind a picture while the beads are prayed.","voice":"brian","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-mystery-sorrowful-2-scourging","title":"The Second Sorrowful Mystery: The Scourging at the Pillar","by":"Douay-Rheims Bible, John 19:1 and Isaias 53:5","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["healing","comfort"],"text":"Then therefore Pilate took Jesus and scourged him.\n\nBut he was wounded for our iniquities, he was bruised for our sins: the chastisement of our peace was upon him, and by his bruises we are healed.","note":"Read aloud before its decade of the Rosary, to give the mind a picture while the beads are prayed.","voice":"jenny","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-mystery-sorrowful-3-crowning","title":"The Third Sorrowful Mystery: The Crowning with Thorns","by":"Douay-Rheims Bible, Matthew 27:29","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["comfort"],"text":"And platting a crown of thorns, they put it upon his head, and a reed in his right hand. And bowing the knee before him, they mocked him, saying: Hail, King of the Jews.","note":"Read aloud before its decade of the Rosary, to give the mind a picture while the beads are prayed.","voice":"brian","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-mystery-sorrowful-4-carrying","title":"The Fourth Sorrowful Mystery: The Carrying of the Cross","by":"Douay-Rheims Bible, John 19:17 and Luke 23:26","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["comfort","grief"],"text":"And bearing his own cross, he went forth to the place which is called Calvary, but in Hebrew Golgotha.\n\nAnd as they led him away, they laid hold of one Simon of Cyrene, coming from the country; and they laid the cross on him to carry after Jesus.","note":"Read aloud before its decade of the Rosary, to give the mind a picture while the beads are prayed.","voice":"jenny","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-mystery-sorrowful-5-crucifixion","title":"The Fifth Sorrowful Mystery: The Crucifixion","by":"Douay-Rheims Bible, Luke 23:33 to 34, 46","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["dying","forgiveness","funeral"],"text":"And when they were come to the place which is called Calvary, they crucified him there: and the robbers, one on the right hand, and the other on the left.\nAnd Jesus said: Father, forgive them, for they know not what they do. But they, dividing his garments, cast lots.\n\nAnd Jesus crying with a loud voice, said: Father, into thy hands I commend my spirit. And saying this, he gave up the ghost.","note":"Read aloud before its decade of the Rosary, to give the mind a picture while the beads are prayed.","voice":"brian","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-mystery-glorious-1-resurrection","title":"The First Glorious Mystery: The Resurrection","by":"Douay-Rheims Bible, Matthew 28:5 to 6","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["hope","funeral","season"],"text":"And the angel answering, said to the women: Fear not you: for I know that you seek Jesus who was crucified.\nHe is not here. For he is risen, as he said. Come, and see the place where the Lord was laid.","note":"Read aloud before its decade of the Rosary, to give the mind a picture while the beads are prayed.","voice":"jenny","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-mystery-glorious-2-ascension","title":"The Second Glorious Mystery: The Ascension","by":"Douay-Rheims Bible, Luke 24:50 to 51","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["blessing","hope"],"text":"And he led them out as far as Bethania: and lifting up his hands, he blessed them.\nAnd it came to pass, whilst he blessed them, he departed from them and was carried up to heaven.","note":"Read aloud before its decade of the Rosary, to give the mind a picture while the beads are prayed.","voice":"brian","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-mystery-glorious-3-pentecost","title":"The Third Glorious Mystery: The Descent of the Holy Spirit","by":"Douay-Rheims Bible, Acts 2:1 to 4","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["blessing","celebration"],"text":"And when the days of the Pentecost were accomplished, they were all together in one place:\nAnd suddenly there came a sound from heaven, as of a mighty wind coming: and it filled the whole house where they were sitting.\nAnd there appeared to them parted tongues, as it were of fire: and it sat upon every one of them.\nAnd they were all filled with the Holy Ghost: and they began to speak with divers tongues, according as the Holy Ghost gave them to speak.","note":"Read aloud before its decade of the Rosary, to give the mind a picture while the beads are prayed.","voice":"jenny","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-mystery-glorious-4-assumption","title":"The Fourth Glorious Mystery: The Assumption","by":"Douay-Rheims Bible, Canticle of Canticles 2:10 to 12","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["hope","dying","nature"],"text":"Behold my beloved speaketh to me: Arise, make haste, my love, my dove, my beautiful one, and come.\nFor winter is now past, the rain is over and gone.\nThe flowers have appeared in our land, the time of pruning is come: the voice of the turtle is heard in our land:","note":"Read aloud before its decade of the Rosary, to give the mind a picture while the beads are prayed.","voice":"brian","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-mystery-glorious-5-coronation","title":"The Fifth Glorious Mystery: The Coronation of Mary","by":"Douay-Rheims Bible, Apocalypse 12:1","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["hope","celebration"],"text":"And a great sign appeared in heaven: A woman clothed with the sun, and the moon under her feet, and on her head a crown of twelve stars.","note":"Read aloud before its decade of the Rosary, to give the mind a picture while the beads are prayed.","voice":"jenny","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-memorare","title":"The Memorare","by":"Traditional, attributed to Saint Bernard of Clairvaux","year":1888,"trad":["catholic"],"type":"prayer","occasion":["comfort","hope","grief"],"text":"Remember, O most gracious Virgin Mary,\nthat never was it known that anyone who fled to thy protection,\nimplored thy help, or sought thy intercession, was left unaided.\n\nInspired by this confidence, I fly unto thee, O Virgin of virgins, my Mother;\nto thee do I come, before thee I stand, sinful and sorrowful.\nO Mother of the Word Incarnate, despise not my petitions,\nbut in thy mercy hear and answer me. Amen.","translit":"Memorare, O piissima Virgo Maria","note":"A prayer of deep trust, prayed in hard waiting and at the bedside.","voice":"brian","source":{"name":"A Manual of Prayers for the Use of the Catholic Laity (1888), Internet Archive","url":"https://archive.org/search?query=%22Manual+of+Prayers+for+the+Use+of+the+Catholic+Laity%22"},"rights":"pd","pd":"Fifteenth century Latin, popularized by Claude Bernard (died 1641); this English form was in prayer books by the 1800s; public domain.","denom":[]},{"id":"cath-saint-michael","title":"Prayer to Saint Michael the Archangel","by":"Pope Leo XIII","year":1886,"trad":["catholic"],"type":"prayer","occasion":["comfort","daily"],"text":"Saint Michael the Archangel, defend us in battle;\nbe our safeguard against the wickedness and snares of the devil.\nMay God rebuke him, we humbly pray;\nand do thou, O Prince of the heavenly host,\nby the power of God, thrust into hell Satan and all the evil spirits\nwho prowl about the world seeking the ruin of souls. Amen.","translit":"Sancte Michael Archangele, defende nos in proelio","note":"A prayer for protection and courage, long said at the end of Mass and in times of trouble.","voice":"jenny","source":{"name":"The Raccolta, English editions (1880s to 1910), Internet Archive","url":"https://archive.org/search?query=Raccolta+indulgenced+prayers"},"rights":"pd","pd":"Composed by Pope Leo XIII and prescribed in 1886; traditional English; public domain.","denom":[]},{"id":"cath-angelus","title":"The Angelus","by":"Traditional","year":1888,"trad":["catholic"],"type":"prayer","occasion":["morning","daily","evening"],"text":"V. The Angel of the Lord declared unto Mary.\nR. And she conceived of the Holy Ghost.\nHail Mary.\n\nV. Behold the handmaid of the Lord.\nR. Be it done unto me according to thy word.\nHail Mary.\n\nV. And the Word was made flesh.\nR. And dwelt among us.\nHail Mary.\n\nV. Pray for us, O holy Mother of God.\nR. That we may be made worthy of the promises of Christ.\n\nLet us pray. Pour forth, we beseech Thee, O Lord, Thy grace into our hearts;\nthat we, to whom the Incarnation of Christ, Thy Son, was made known by the message of an angel,\nmay by His Passion and Cross be brought to the glory of His Resurrection.\nThrough the same Christ our Lord. Amen.","translit":"Angelus Domini nuntiavit Mariae","note":"Prayed at six in the morning, noon, and six in the evening, often at the ringing of a bell.","voice":"brian","source":{"name":"A Manual of Prayers for the Use of the Catholic Laity (1888), Internet Archive","url":"https://archive.org/search?query=%22Manual+of+Prayers+for+the+Use+of+the+Catholic+Laity%22"},"rights":"pd","pd":"Medieval devotion; this English form was in Catholic prayer books by the 1800s; public domain.","denom":[]},{"id":"cath-regina-caeli","title":"Queen of Heaven, Rejoice","by":"Traditional","year":1888,"trad":["catholic"],"type":"prayer","occasion":["season","celebration","hope"],"text":"Queen of Heaven, rejoice, alleluia.\nFor He whom thou didst merit to bear, alleluia,\nHas risen, as He said, alleluia.\nPray for us to God, alleluia.\n\nV. Rejoice and be glad, O Virgin Mary, alleluia.\nR. For the Lord has truly risen, alleluia.\n\nLet us pray. O God, who gavest joy to the world through the resurrection of Thy Son, our Lord Jesus Christ,\ngrant, we beseech Thee, that through the intercession of the Virgin Mary, His Mother,\nwe may obtain the joys of everlasting life. Through the same Christ our Lord. Amen.","translit":"Regina caeli, laetare, alleluia","note":"Prayed in place of the Angelus through the Easter season.","voice":"jenny","source":{"name":"A Manual of Prayers for the Use of the Catholic Laity (1888), Internet Archive","url":"https://archive.org/search?query=%22Manual+of+Prayers+for+the+Use+of+the+Catholic+Laity%22"},"rights":"pd","pd":"The Regina Caeli, twelfth century; this English form was in prayer books by the 1800s; public domain.","denom":[]},{"id":"cath-eternal-rest","title":"Eternal Rest","by":"Traditional","year":1888,"trad":["catholic","christian"],"denom":["requiem"],"type":"prayer","occasion":["funeral","grief","dying"],"text":"Eternal rest grant unto them, O Lord,\nand let perpetual light shine upon them.\nMay they rest in peace. Amen.\n\nMay their souls, and the souls of all the faithful departed,\nthrough the mercy of God, rest in peace. Amen.","translit":"Requiem aeternam dona eis, Domine","note":"Said for the one who has died, at the bedside, the wake, the graveside, and on every anniversary.","voice":"brian","source":{"name":"A Manual of Prayers for the Use of the Catholic Laity (1888), Internet Archive","url":"https://archive.org/search?query=%22Manual+of+Prayers+for+the+Use+of+the+Catholic+Laity%22"},"rights":"pd","pd":"From the Requiem Mass, 2 Esdras 2:34 to 35; this English form was in prayer books by the 1800s; public domain."},{"id":"cath-anima-christi","title":"Soul of Christ","by":"Traditional, translated by John Henry Newman","tr":"John Henry Newman","year":1893,"trad":["catholic"],"type":"prayer","occasion":["dying","comfort","healing"],"text":"Soul of Christ, be my sanctification;\nBody of Christ, be my salvation;\nBlood of Christ, fill all my veins;\nWater of Christ's side, wash out my stains;\nPassion of Christ, my comfort be;\nO good Jesu, listen to me;\nIn Thy wounds I fain would hide,\nNe'er to be parted from Thy side;\nGuard me, should the foe assail me;\nCall me when my life shall fail me;\nBid me come to Thee above,\nWith Thy saints to sing Thy love,\nWorld without end. Amen.","translit":"Anima Christi, sanctifica me","note":"The Anima Christi, loved by Saint Ignatius, prayed after Communion and in the last days of life.","voice":"jenny","source":{"name":"John Henry Newman, Meditations and Devotions (1893), Newman Reader","url":"https://www.newmanreader.org/works/meditations/index.html"},"rights":"pd","pd":"Fourteenth century Latin; translation by Newman, died 1890, published 1893; public domain.","denom":[]},{"id":"cath-act-of-contrition","title":"An Act of Contrition","by":"Traditional","year":1891,"trad":["catholic"],"type":"prayer","occasion":["forgiveness","dying","evening"],"text":"O my God, I am heartily sorry for having offended Thee,\nand I detest all my sins, because I dread the loss of heaven and the pains of hell;\nbut most of all because they offend Thee, my God,\nwho art all good and deserving of all my love.\nI firmly resolve, with the help of Thy grace,\nto confess my sins, to do penance, and to amend my life. Amen.","note":"Prayed in confession, at the close of the day, and by many Catholics in their last hours.","voice":"brian","source":{"name":"Baltimore Catechism (1891), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/search/?query=baltimore+catechism"},"rights":"pd","pd":"From the Baltimore Catechism, 1891; public domain.","denom":[]},{"id":"cath-act-of-faith","title":"An Act of Faith","by":"Traditional","year":1891,"trad":["catholic"],"type":"prayer","occasion":["daily","morning"],"text":"O my God, I firmly believe that Thou art one God in three divine Persons, Father, Son, and Holy Ghost.\nI believe that Thy divine Son became man, and died for our sins,\nand that He will come to judge the living and the dead.\nI believe these and all the truths which the holy Catholic Church teaches,\nbecause Thou hast revealed them, who canst neither deceive nor be deceived. Amen.","note":"One of the three acts many Catholics learned as children and pray each morning.","voice":"jenny","source":{"name":"Baltimore Catechism (1891), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/search/?query=baltimore+catechism"},"rights":"pd","pd":"From the Baltimore Catechism, 1891; public domain.","denom":[]},{"id":"cath-act-of-hope","title":"An Act of Hope","by":"Traditional","year":1891,"trad":["catholic"],"type":"prayer","occasion":["hope","dying","comfort"],"text":"O my God, relying on Thy infinite goodness and promises,\nI hope to obtain pardon of my sins, the help of Thy grace,\nand life everlasting, through the merits of Jesus Christ, my Lord and Redeemer. Amen.","note":"A short prayer of hope, gentle to pray with someone who is very ill.","voice":"brian","source":{"name":"Baltimore Catechism (1891), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/search/?query=baltimore+catechism"},"rights":"pd","pd":"From the Baltimore Catechism, 1891; public domain.","denom":[]},{"id":"cath-act-of-love","title":"An Act of Love","by":"Traditional","year":1891,"trad":["catholic"],"type":"prayer","occasion":["daily","forgiveness","peace"],"text":"O my God, I love Thee above all things, with my whole heart and soul,\nbecause Thou art all good and worthy of all love.\nI love my neighbor as myself for the love of Thee.\nI forgive all who have injured me, and ask pardon of all whom I have injured. Amen.","note":"A prayer of love and forgiveness, often prayed when a family is making peace.","voice":"jenny","source":{"name":"Baltimore Catechism (1891), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/search/?query=baltimore+catechism"},"rights":"pd","pd":"From the Baltimore Catechism, 1891; public domain.","denom":[]},{"id":"cath-guardian-angel","title":"Angel of God","by":"Traditional","year":1888,"trad":["catholic"],"type":"prayer","occasion":["morning","evening","home"],"text":"Angel of God, my guardian dear,\nto whom God's love commits me here,\never this day be at my side,\nto light and guard, to rule and guide. Amen.","translit":"Angele Dei, qui custos es mei","note":"A child's first prayer in many Catholic homes, said at bedtime and in the morning.","voice":"brian","source":{"name":"A Manual of Prayers for the Use of the Catholic Laity (1888), Internet Archive","url":"https://archive.org/search?query=%22Manual+of+Prayers+for+the+Use+of+the+Catholic+Laity%22"},"rights":"pd","pd":"Traditional prayer, English form in Catholic prayer books by the 1800s; public domain.","denom":[]},{"id":"cath-come-holy-spirit","title":"Come, Holy Spirit","by":"Traditional","year":1888,"trad":["catholic"],"type":"prayer","occasion":["morning","blessing"],"text":"Come, Holy Ghost, fill the hearts of Thy faithful,\nand kindle in them the fire of Thy love.\n\nV. Send forth Thy Spirit, and they shall be created.\nR. And Thou shalt renew the face of the earth.\n\nLet us pray. O God, who didst instruct the hearts of the faithful by the light of the Holy Spirit,\ngrant us in the same Spirit to be truly wise, and ever to rejoice in His consolation.\nThrough Christ our Lord. Amen.","translit":"Veni, Sancte Spiritus","note":"Prayed to begin a meeting, a study, a decision, or a day.","voice":"jenny","source":{"name":"A Manual of Prayers for the Use of the Catholic Laity (1888), Internet Archive","url":"https://archive.org/search?query=%22Manual+of+Prayers+for+the+Use+of+the+Catholic+Laity%22"},"rights":"pd","pd":"Traditional prayer and collect; this English form was in prayer books by the 1800s; public domain.","denom":[]},{"id":"cath-morning-offering","title":"The Morning Offering","by":"Traditional, Apostleship of Prayer","year":1888,"trad":["catholic"],"type":"prayer","occasion":["morning","daily"],"text":"O Jesus, through the Immaculate Heart of Mary,\nI offer Thee my prayers, works, joys, and sufferings of this day,\nfor all the intentions of Thy Sacred Heart,\nin union with the Holy Sacrifice of the Mass throughout the world,\nin reparation for my sins, for the intentions of all our associates,\nand in particular for the intention recommended this month by the Holy Father. Amen.","note":"Prayed on waking, to give the whole day to God.","voice":"brian","source":{"name":"A Manual of Prayers for the Use of the Catholic Laity (1888), Internet Archive","url":"https://archive.org/search?query=%22Manual+of+Prayers+for+the+Use+of+the+Catholic+Laity%22"},"rights":"pd","pd":"From the Apostleship of Prayer, founded 1844; English in prayer books by the 1880s; public domain. Wording varies a little between books.","denom":[]},{"id":"cath-grace-before-meals","title":"Grace Before Meals","by":"Traditional","year":1888,"trad":["catholic","christian"],"type":"prayer","occasion":["daily","gratitude","home"],"text":"Bless us, O Lord, and these Thy gifts,\nwhich we are about to receive from Thy bounty,\nthrough Christ our Lord. Amen.","note":"The table grace of countless Catholic homes, lovely at a family meal after a funeral.","voice":"jenny","source":{"name":"A Manual of Prayers for the Use of the Catholic Laity (1888), Internet Archive","url":"https://archive.org/search?query=%22Manual+of+Prayers+for+the+Use+of+the+Catholic+Laity%22"},"rights":"pd","pd":"Traditional grace; English form in prayer books by the 1800s; public domain.","denom":[]},{"id":"cath-grace-after-meals","title":"Grace After Meals","by":"Traditional","year":1888,"trad":["catholic"],"type":"prayer","occasion":["daily","gratitude","grief"],"text":"We give Thee thanks, almighty God, for all Thy benefits,\nwho livest and reignest, world without end. Amen.\n\nMay the souls of the faithful departed,\nthrough the mercy of God, rest in peace. Amen.","note":"Said after a meal, remembering those who have died.","voice":"brian","source":{"name":"A Manual of Prayers for the Use of the Catholic Laity (1888), Internet Archive","url":"https://archive.org/search?query=%22Manual+of+Prayers+for+the+Use+of+the+Catholic+Laity%22"},"rights":"pd","pd":"Traditional grace; English form in prayer books by the 1800s; public domain.","denom":[]},{"id":"cath-suscipe","title":"Take, Lord, and Receive","by":"Saint Ignatius of Loyola","tr":"Elder Mullan","year":1914,"trad":["catholic"],"denom":["jesuit"],"type":"prayer","occasion":["dying","peace","daily"],"text":"Take, Lord, and receive all my liberty, my memory, my understanding, and all my will,\nall that I have and possess.\nThou gavest it to me: to Thee, Lord, I return it.\nAll is Thine, dispose of it according to all Thy will.\nGive me Thy love and grace, for this is enough for me.","note":"The Suscipe, from the Spiritual Exercises, a prayer of letting go into God's hands.","voice":"jenny","source":{"name":"The Spiritual Exercises of St. Ignatius, translated by Elder Mullan (1914), Internet Archive","url":"https://archive.org/search?query=Spiritual+Exercises+Ignatius+Mullan+1914"},"rights":"pd","pd":"Written by Ignatius (died 1556); Mullan translation published 1914; public domain."},{"id":"cath-prayer-for-generosity","title":"Prayer for Generosity","by":"Attributed to Saint Ignatius of Loyola","year":1890,"trad":["catholic","christian"],"denom":["jesuit"],"type":"prayer","occasion":["daily","morning"],"text":"Teach us, good Lord, to serve Thee as Thou deservest;\nto give, and not to count the cost;\nto fight, and not to heed the wounds;\nto toil, and not to seek for rest;\nto labour, and not to ask for any reward,\nsave that of knowing that we do Thy will.","note":"A prayer for anyone who serves others, beloved by caregivers and chaplains.","voice":"brian","source":{"name":"Prayer for Generosity, history and text, Wikipedia","url":"https://en.wikipedia.org/wiki/Prayer_for_Generosity"},"rights":"pd","pd":"Traditionally attributed to Ignatius (died 1556); in English print by the 1800s; public domain."},{"id":"cath-teresa-bookmark","title":"Saint Teresa's Bookmark","by":"Saint Teresa of Avila","tr":"Henry Wadsworth Longfellow","year":1867,"trad":["catholic","all"],"denom":["carmelite"],"type":"prayer","occasion":["comfort","peace","grief"],"text":"Let nothing disturb thee,\nNothing affright thee;\nAll things are passing;\nGod never changeth;\nPatient endurance\nAttaineth to all things;\nWho God possesseth\nIn nothing is wanting;\nAlone God sufficeth.","translit":"Nada te turbe, nada te espante","note":"Found in Teresa's prayer book after her death, a steady word for anxious hours.","voice":"jenny","source":{"name":"Henry Wadsworth Longfellow, Santa Teresa's Book-Mark, in his collected poems, Project Gutenberg","url":"https://www.gutenberg.org/ebooks/search/?query=longfellow+poetical+works"},"rights":"pd","pd":"Written by Teresa (died 1582); Longfellow's translation, Longfellow died 1882; public domain."},{"id":"cath-aquinas-steadfast-heart","title":"For a Steadfast Heart","by":"Saint Thomas Aquinas","year":1880,"trad":["catholic","christian"],"denom":["dominican"],"type":"prayer","occasion":["comfort","daily"],"text":"Give me, O Lord, a steadfast heart, which no unworthy affection may drag downwards;\ngive me an unconquered heart, which no tribulation can wear out;\ngive me an upright heart, which no unworthy purpose may tempt aside.\n\nBestow on me also, O Lord my God, understanding to know Thee,\ndiligence to seek Thee, wisdom to find Thee,\nand a faithfulness that may finally embrace Thee;\nthrough Jesus Christ our Lord. Amen.","note":"A prayer for strength and clear purpose in a long, hard season.","voice":"brian","source":{"name":"Prayers of Saint Thomas Aquinas, in nineteenth century English devotional collections, Internet Archive","url":"https://archive.org/search?query=prayers+of+St.+Thomas+Aquinas"},"rights":"pd","pd":"Written by Aquinas (died 1274); English form in print by the late 1800s; public domain."},{"id":"cath-augustine-restless","title":"Our Heart Is Restless","by":"Saint Augustine of Hippo","tr":"Edward Bouverie Pusey","year":1838,"trad":["catholic","christian","all"],"denom":["augustinian"],"type":"reflection","occasion":["comfort","peace"],"text":"Great art Thou, O Lord, and greatly to be praised;\ngreat is Thy power, and Thy wisdom infinite.\n\nThou awakest us to delight in Thy praise;\nfor Thou madest us for Thyself,\nand our heart is restless, until it repose in Thee.","note":"From the first page of the Confessions, words that have comforted seekers for sixteen hundred years.","voice":"jenny","source":{"name":"The Confessions of Saint Augustine, translated by Edward Bouverie Pusey (1838), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/3296"},"rights":"pd","pd":"Written about 400; Pusey translation 1838; public domain."},{"id":"cath-augustine-late-have-i-loved","title":"Too Late Loved I Thee","by":"Saint Augustine of Hippo","tr":"Edward Bouverie Pusey","year":1838,"trad":["catholic","christian"],"denom":["augustinian"],"type":"reflection","occasion":["hope","forgiveness"],"text":"Too late loved I Thee, O Thou Beauty of ancient days, yet ever new!\ntoo late I loved Thee!\nAnd behold, Thou wert within, and I abroad, and there I searched for Thee.\n\nThou wert with me, but I was not with Thee.\n\nThou calledst, and shoutedst, and burstest my deafness.\nThou flashedst, shonest, and scatteredst my blindness.\nThou breathedst odours, and I drew in breath and panted for Thee.\nI tasted, and hunger and thirst.\nThou touchedst me, and I burned for Thy peace.","note":"From Confessions, Book 10, a song of coming home to God at any age.","voice":"brian","source":{"name":"The Confessions of Saint Augustine, translated by Edward Bouverie Pusey (1838), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/3296"},"rights":"pd","pd":"Written about 400; Pusey translation 1838; public domain."},{"id":"cath-newman-mission","title":"Some Definite Service","by":"John Henry Newman","year":1893,"trad":["catholic","christian","all"],"type":"reflection","occasion":["comfort","hope","healing"],"text":"God has created me to do Him some definite service;\nHe has committed some work to me which He has not committed to another.\nI have my mission; I may never know it in this life, but I shall be told it in the next.\n\nI am a link in a chain, a bond of connexion between persons.\nHe has not created me for naught. I shall do good, I shall do His work.\n\nTherefore I will trust Him. Whatever, wherever I am, I can never be thrown away.\nIf I am in sickness, my sickness may serve Him;\nin perplexity, my perplexity may serve Him;\nif I am in sorrow, my sorrow may serve Him.\nHe does nothing in vain. He knows what He is about.","note":"A favorite for anyone wondering whether a life in illness or old age still has purpose.","voice":"jenny","source":{"name":"John Henry Newman, Meditations and Devotions (1893), Newman Reader","url":"https://www.newmanreader.org/works/meditations/index.html"},"rights":"pd","pd":"Written 1848; Newman died 1890; published 1893; public domain.","denom":[]},{"id":"cath-newman-last-hour","title":"For the Last Hour","by":"John Henry Newman","year":1893,"trad":["catholic"],"type":"prayer","occasion":["dying"],"text":"O my Lord and Saviour, support me in my last hour in the strong arms of Thy Sacraments,\nand by the fresh fragrance of Thy consolations.\nLet the absolving words be said over me, and the holy oil sign and seal me,\nand Thy own Body be my food, and Thy Blood my sprinkling;\nand let my sweet Mother, Mary, breathe on me, and my Angel whisper peace to me,\nand my glorious Saints smile upon me;\nthat in them all, and through them all, I may receive the gift of perseverance,\nand die, as I desire to live, in Thy faith, in Thy Church, in Thy service, and in Thy love. Amen.","note":"A Catholic's prayer for a holy death, lovely to pray with someone receiving the last sacraments.","voice":"brian","source":{"name":"John Henry Newman, Meditations and Devotions (1893), Newman Reader","url":"https://www.newmanreader.org/works/meditations/index.html"},"rights":"pd","pd":"Newman died 1890; published 1893; public domain.","denom":[]},{"id":"cath-lead-kindly-light","title":"Lead, Kindly Light","by":"John Henry Newman","year":1833,"trad":["catholic","episcopal","christian","all"],"type":"hymn","occasion":["comfort","hope","funeral"],"text":"Lead, Kindly Light, amid the encircling gloom,\nLead Thou me on!\nThe night is dark, and I am far from home;\nLead Thou me on!\nKeep Thou my feet; I do not ask to see\nThe distant scene; one step enough for me.\n\nI was not ever thus, nor prayed that Thou\nShouldst lead me on;\nI loved to choose and see my path; but now\nLead Thou me on!\nI loved the garish day, and, spite of fears,\nPride ruled my will: remember not past years!\n\nSo long Thy power hath blest me, sure it still\nWill lead me on,\nO'er moor and fen, o'er crag and torrent, till\nThe night is gone,\nAnd with the morn those angel faces smile,\nWhich I have loved long since, and lost awhile!","note":"Written at sea in 1833, sung at funerals for its last line about faces loved and lost awhile.","voice":"jenny","source":{"name":"Hymnary.org","url":"https://hymnary.org/search?qu=Lead+kindly+light+amid+the+encircling+gloom"},"rights":"pd","pd":"Written 1833; Newman died 1890; public domain.","denom":[]},{"id":"cath-canticle-of-the-sun","title":"The Canticle of the Sun","by":"Saint Francis of Assisi","tr":"Matthew Arnold","year":1865,"trad":["catholic","christian","nature","all"],"denom":["franciscan"],"type":"prayer","occasion":["nature","gratitude","dying"],"text":"O most high, almighty, good Lord God, to thee belong praise, glory, honour, and all blessing!\n\nPraised be my Lord God with all his creatures; and specially our brother the sun, who brings us the day, and who brings us the light; fair is he, and shines with a very great splendour: O Lord, he signifies to us thee!\n\nPraised be my Lord for our sister the moon, and for the stars, the which he has set clear and lovely in heaven.\n\nPraised be my Lord for our brother the wind, and for air and cloud, calms and all weather, by the which thou upholdest life in all creatures.\n\nPraised be my Lord for our sister water, who is very serviceable unto us, and humble, and precious, and clean.\n\nPraised be my Lord for our brother fire, through whom thou givest us light in the darkness; and he is bright, and pleasant, and very mighty, and strong.\n\nPraised be my Lord for our mother the earth, the which doth sustain us and keep us, and bringeth forth divers fruits, and flowers of many colours, and grass.\n\nPraised be my Lord for all those who pardon one another for his love's sake, and who endure weakness and tribulation; blessed are they who peaceably shall endure, for thou, O most Highest, shalt give them a crown!\n\nPraised be my Lord for our sister, the death of the body, from whom no man escapeth. Blessed are they who are found walking by thy most holy will.\n\nPraise ye and bless ye the Lord, and give thanks unto him, and serve him with great humility.","note":"Francis sang the last verse, welcoming Sister Death, near the end of his life; loved at nature funerals.","voice":"brian","source":{"name":"Matthew Arnold, Essays in Criticism (1865), Pagan and Mediaeval Religious Sentiment, Project Gutenberg","url":"https://www.gutenberg.org/ebooks/search/?query=matthew+arnold+essays+in+criticism"},"rights":"pd","pd":"Written by Francis in 1225; Arnold's translation 1865, Arnold died 1888; public domain. One line on mortal sin is left out of this reading."},{"id":"cath-peace-prayer","title":"The Peace Prayer","by":"Traditional, long attributed to Saint Francis","year":1927,"trad":["catholic","christian","all"],"denom":["franciscan"],"type":"prayer","occasion":["peace","forgiveness","daily"],"text":"Lord, make me an instrument of your peace.\nWhere there is hatred, let me sow love;\nwhere there is injury, pardon;\nwhere there is doubt, faith;\nwhere there is despair, hope;\nwhere there is darkness, light;\nand where there is sadness, joy.\n\nO Divine Master, grant that I may not so much seek\nto be consoled, as to console;\nto be understood, as to understand;\nto be loved, as to love.\nFor it is in giving that we receive;\nit is in pardoning that we are pardoned;\nand it is in dying that we are born to eternal life.","note":"First printed in French in 1912 with no author; it was linked to Francis around 1920 and is now beloved by all faith traditions.","voice":"jenny","source":{"name":"Quote Investigator, Lord, Make Me an Instrument of Your Peace (history, with the 1927 English printing)","url":"https://quoteinvestigator.com/2011/12/22/prayer-assisi/"},"rights":"pd","pd":"Anonymous French prayer, La Clochette, 1912; first known English in Friends' Intelligencer, January 22, 1927; public domain. Match the wording to the 1927 printing."},{"id":"cath-jesus-the-very-thought","title":"Jesus, the Very Thought of Thee","by":"Attributed to Saint Bernard of Clairvaux","tr":"Edward Caswall","year":1849,"trad":["catholic","christian"],"denom":["cistercian"],"type":"hymn","occasion":["comfort","daily"],"text":"Jesus, the very thought of Thee\nWith sweetness fills the breast;\nBut sweeter far Thy face to see,\nAnd in Thy presence rest.\n\nNor voice can sing, nor heart can frame,\nNor can the memory find\nA sweeter sound than Thy blest Name,\nO Saviour of mankind!\n\nO hope of every contrite heart,\nO joy of all the meek,\nTo those who fall, how kind Thou art!\nHow good to those who seek!\n\nBut what to those who find? Ah, this\nNor tongue nor pen can show;\nThe love of Jesus, what it is\nNone but His loved ones know.\n\nJesus, our only joy be Thou,\nAs Thou our prize wilt be;\nJesus, be Thou our glory now,\nAnd through eternity.","note":"A gentle hymn of longing and rest, spoken softly at a bedside.","voice":"brian","source":{"name":"Hymnary.org","url":"https://hymnary.org/search?qu=Jesus+the+very+thought+of+thee"},"rights":"pd","pd":"Latin Jesu dulcis memoria, twelfth century; Edward Caswall translation 1849, Caswall died 1878; public domain."},{"id":"cath-stabat-mater","title":"At the Cross Her Station Keeping","by":"Traditional, Stabat Mater","tr":"Edward Caswall","year":1849,"trad":["catholic"],"type":"hymn","occasion":["grief","season","comfort"],"text":"At the Cross her station keeping,\nStood the mournful Mother weeping,\nClose to Jesus to the last.\n\nThrough her heart, His sorrow sharing,\nAll His bitter anguish bearing,\nNow at length the sword has passed.\n\nO how sad and sore distressed\nWas that Mother highly blest\nOf the sole begotten One!\n\nChrist above in torment hangs;\nShe beneath beholds the pangs\nOf her dying glorious Son.","translit":"Stabat mater dolorosa","note":"The hymn of Mary's grief, sung at the Stations of the Cross; a companion for any parent who grieves a child.","voice":"jenny","source":{"name":"Hymnary.org","url":"https://hymnary.org/search?qu=At+the+cross+her+station+keeping"},"rights":"pd","pd":"Latin, thirteenth century; Edward Caswall translation 1849, Caswall died 1878; public domain.","denom":[]},{"id":"cath-holy-god-we-praise","title":"Holy God, We Praise Thy Name","by":"Traditional, Te Deum","tr":"Clarence A. Walworth","year":1858,"trad":["catholic","christian"],"type":"hymn","occasion":["celebration","gratitude","funeral"],"text":"Holy God, we praise Thy Name;\nLord of all, we bow before Thee!\nAll on earth Thy sceptre claim,\nAll in heaven above adore Thee;\nInfinite Thy vast domain,\nEverlasting is Thy reign.\n\nHark! the loud celestial hymn\nAngel choirs above are raising,\nCherubim and Seraphim,\nIn unceasing chorus praising;\nFill the heavens with sweet accord:\nHoly, holy, holy, Lord.\n\nHoly Father, Holy Son,\nHoly Spirit, Three we name Thee;\nWhile in essence only One,\nUndivided God we claim Thee;\nAnd adoring bend the knee,\nWhile we own the mystery.","note":"A great hymn of praise, often the closing hymn at a Catholic funeral or celebration of life.","voice":"brian","source":{"name":"Hymnary.org","url":"https://hymnary.org/search?qu=Holy+God+we+praise+thy+name"},"rights":"pd","pd":"German Grosser Gott, 1771; Clarence Walworth translation 1858, Walworth died 1900; public domain.","denom":[]},{"id":"cath-down-in-adoration","title":"Down in Adoration Falling","by":"Saint Thomas Aquinas","tr":"Edward Caswall","year":1849,"trad":["catholic"],"denom":["dominican"],"type":"hymn","occasion":["daily","blessing"],"text":"Down in adoration falling,\nLo! the sacred Host we hail;\nLo! o'er ancient forms departing,\nNewer rites of grace prevail;\nFaith for all defects supplying,\nWhere the feeble senses fail.\n\nTo the everlasting Father,\nAnd the Son who reigns on high,\nWith the Holy Ghost proceeding\nForth from Each eternally,\nBe salvation, honour, blessing,\nMight, and endless majesty. Amen.","translit":"Tantum ergo Sacramentum","note":"The Tantum Ergo, sung at Benediction of the Blessed Sacrament.","voice":"jenny","source":{"name":"Hymnary.org","url":"https://hymnary.org/search?qu=Down+in+adoration+falling"},"rights":"pd","pd":"Written by Aquinas, 1264; Edward Caswall translation 1849; public domain."},{"id":"cath-adoro-te","title":"Godhead Here in Hiding","by":"Saint Thomas Aquinas","tr":"Gerard Manley Hopkins","year":1918,"trad":["catholic"],"denom":["dominican","jesuit"],"type":"hymn","occasion":["daily","dying"],"text":"Godhead here in hiding, whom I do adore,\nMasked by these bare shadows, shape and nothing more,\nSee, Lord, at thy service low lies here a heart\nLost, all lost in wonder at the God thou art.\n\nSeeing, touching, tasting are in thee deceived:\nHow says trusty hearing? that shall be believed;\nWhat God's Son has told me, take for truth I do;\nTruth himself speaks truly or there's nothing true.\n\nJesu whom I look at shrouded here below,\nI beseech thee send me what I thirst for so,\nSome day to gaze on thee face to face in light\nAnd be blest for ever with thy glory's sight.","translit":"Adoro te devote, latens Deitas","note":"From the Adoro Te Devote, in the poet Gerard Manley Hopkins's translation.","voice":"brian","source":{"name":"Poems of Gerard Manley Hopkins (1918), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/search/?query=hopkins+poems"},"rights":"pd","pd":"Written by Aquinas, thirteenth century; Hopkins translation, Hopkins died 1889, published 1918; public domain."},{"id":"cath-when-morning-gilds","title":"When Morning Gilds the Skies","by":"Traditional German hymn","tr":"Edward Caswall","year":1854,"trad":["catholic","christian"],"type":"hymn","occasion":["morning","gratitude","celebration"],"text":"When morning gilds the skies,\nMy heart awaking cries:\nMay Jesus Christ be praised!\nAlike at work and prayer\nTo Jesus I repair:\nMay Jesus Christ be praised!\n\nBe this, while life is mine,\nMy canticle divine:\nMay Jesus Christ be praised!\nBe this the eternal song\nThrough all the ages long:\nMay Jesus Christ be praised!","note":"A bright morning hymn, joyful for a celebration of life.","voice":"jenny","source":{"name":"Hymnary.org","url":"https://hymnary.org/search?qu=When+morning+gilds+the+skies"},"rights":"pd","pd":"German, 1828; Edward Caswall translation 1854; public domain.","denom":[]},{"id":"cath-wideness-in-mercy","title":"There's a Wideness in God's Mercy","by":"Frederick William Faber","year":1854,"trad":["catholic","christian","all"],"denom":["oratorian"],"type":"hymn","occasion":["comfort","forgiveness","funeral"],"text":"There's a wideness in God's mercy,\nLike the wideness of the sea;\nThere's a kindness in His justice,\nWhich is more than liberty.\n\nThere is welcome for the sinner,\nAnd more graces for the good;\nThere is mercy with the Saviour;\nThere is healing in His blood.\n\nFor the love of God is broader\nThan the measure of man's mind;\nAnd the heart of the Eternal\nIs most wonderfully kind.\n\nIf our love were but more simple,\nWe should take Him at His word;\nAnd our lives would be all sunshine\nIn the sweetness of our Lord.","note":"A gentle hymn of welcome and mercy, healing for families who worry about a loved one's soul.","voice":"brian","source":{"name":"Hymnary.org","url":"https://hymnary.org/search?qu=There's+a+wideness+in+God's+mercy"},"rights":"pd","pd":"Written by Faber, 1854; Faber died 1863; public domain."},{"id":"cath-magnificat","title":"The Magnificat","by":"Douay-Rheims Bible, Luke 1:46 to 55","year":1752,"trad":["catholic","christian"],"type":"scripture","occasion":["gratitude","evening","celebration","birth"],"text":"And Mary said: My soul doth magnify the Lord.\nAnd my spirit hath rejoiced in God my Saviour.\nBecause he hath regarded the humility of his handmaid: for behold from henceforth all generations shall call me blessed.\nBecause he that is mighty hath done great things to me: and holy is his name.\nAnd his mercy is from generation unto generations, to them that fear him.\nHe hath shewed might in his arm: he hath scattered the proud in the conceit of their heart.\nHe hath put down the mighty from their seat and hath exalted the humble.\nHe hath filled the hungry with good things: and the rich he hath sent empty away.\nHe hath received Israel his servant, being mindful of his mercy.\nAs he spoke to our fathers: to Abraham and to his seed for ever.","translit":"Magnificat anima mea Dominum","note":"Mary's song of joy, prayed every evening at Vespers and at the birth of a child.","voice":"jenny","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain.","denom":[]},{"id":"cath-sub-tuum","title":"We Fly to Thy Patronage","by":"Traditional, third century","year":1888,"trad":["catholic","orthodox"],"type":"prayer","occasion":["comfort","healing"],"text":"We fly to thy patronage, O holy Mother of God;\ndespise not our petitions in our necessities,\nbut deliver us always from all dangers,\nO glorious and blessed Virgin. Amen.","translit":"Sub tuum praesidium confugimus","note":"The oldest known prayer to Mary, found on a papyrus from about the third century, shared by East and West.","voice":"brian","source":{"name":"A Manual of Prayers for the Use of the Catholic Laity (1888), Internet Archive","url":"https://archive.org/search?query=%22Manual+of+Prayers+for+the+Use+of+the+Catholic+Laity%22"},"rights":"pd","pd":"Sub tuum praesidium, about 250; English form in prayer books by the 1800s; public domain.","denom":[]},{"id":"cath-richard-of-chichester","title":"Day by Day","by":"Saint Richard of Chichester","year":1880,"trad":["catholic","episcopal","christian"],"type":"prayer","occasion":["daily","gratitude"],"text":"Thanks be to Thee, my Lord Jesus Christ,\nfor all the benefits which Thou hast given me,\nfor all the pains and insults which Thou hast borne for me.\nO most merciful Redeemer, Friend, and Brother,\nmay I know Thee more clearly,\nlove Thee more dearly,\nand follow Thee more nearly,\nday by day. Amen.","note":"The prayer of a thirteenth century bishop, said on his deathbed, loved by Catholics and Anglicans alike.","voice":"jenny","source":{"name":"Richard of Chichester, prayer and history, Wikipedia","url":"https://en.wikipedia.org/wiki/Richard_of_Chichester"},"rights":"pd","pd":"Prayed by Richard (died 1253); traditional English form; public domain. Confirm this wording against an early print source.","denom":[]},{"id":"cath-divine-praises","title":"The Divine Praises","by":"Traditional","year":1921,"trad":["catholic"],"type":"litany","occasion":["gratitude","celebration"],"text":"Blessed be God.\nBlessed be His holy Name.\nBlessed be Jesus Christ, true God and true Man.\nBlessed be the Name of Jesus.\nBlessed be His most Sacred Heart.\nBlessed be Jesus in the most holy Sacrament of the Altar.\nBlessed be the great Mother of God, Mary most holy.\nBlessed be her holy and Immaculate Conception.\nBlessed be the name of Mary, Virgin and Mother.\nBlessed be Saint Joseph, her most chaste spouse.\nBlessed be God in His Angels and in His Saints.","note":"A litany of blessing, prayed at Benediction; each line is repeated by all.","voice":"brian","source":{"name":"The Raccolta, English editions (1880s to 1910), Internet Archive","url":"https://archive.org/search?query=Raccolta+indulgenced+prayers"},"rights":"pd","pd":"Composed by Luigi Felici, 1797, with lines added through 1921; this is the 1921 form; public domain.","denom":[]},{"id":"cath-o-sacrament","title":"O Sacrament Most Holy","by":"Traditional","year":1888,"trad":["catholic"],"type":"prayer","occasion":["gratitude","daily"],"text":"O Sacrament most holy, O Sacrament divine,\nall praise and all thanksgiving be every moment Thine.","note":"A short prayer of thanks, often repeated three times.","voice":"jenny","source":{"name":"The Raccolta, English editions (1880s to 1910), Internet Archive","url":"https://archive.org/search?query=Raccolta+indulgenced+prayers"},"rights":"pd","pd":"Traditional prayer in English prayer books by the 1800s; public domain.","denom":[]},{"id":"cath-jesus-mary-joseph","title":"Jesus, Mary, and Joseph","by":"Traditional","year":1888,"trad":["catholic"],"type":"prayer","occasion":["dying","comfort"],"text":"Jesus, Mary, and Joseph, I give you my heart and my soul.\nJesus, Mary, and Joseph, assist me in my last agony.\nJesus, Mary, and Joseph, may I breathe forth my soul in peace with you.","note":"A short prayer for a holy death, easy to whisper again and again at the bedside.","voice":"brian","source":{"name":"The Raccolta, English editions (1880s to 1910), Internet Archive","url":"https://archive.org/search?query=Raccolta+indulgenced+prayers"},"rights":"pd","pd":"Traditional prayer from the Raccolta, English editions from the 1800s; public domain.","denom":[]},{"id":"cath-prayer-before-crucifix","title":"Prayer Before a Crucifix","by":"Traditional","year":1888,"trad":["catholic"],"type":"prayer","occasion":["comfort","forgiveness","season"],"text":"Look down upon me, good and gentle Jesus,\nwhile before Thy face I humbly kneel,\nand with burning soul pray and beseech Thee\nto fix deep in my heart lively sentiments of faith, hope, and charity,\ntrue contrition for my sins, and a firm purpose of amendment;\nwhile I contemplate, with great love and tender pity,\nThy five most precious wounds,\npondering over them within me,\nand calling to mind the words which David, Thy prophet, said of Thee, my Jesus:\nThey have pierced My hands and My feet; they have numbered all My bones.","translit":"En ego, O bone et dulcissime Iesu","note":"The En ego, prayed after Communion and before a crucifix, especially in Lent.","voice":"jenny","source":{"name":"The Raccolta, English editions (1880s to 1910), Internet Archive","url":"https://archive.org/search?query=Raccolta+indulgenced+prayers"},"rights":"pd","pd":"Traditional Latin En ego; English form in prayer books by the 1800s; public domain.","denom":[]},{"id":"cath-veni-creator","title":"Come, Holy Ghost, Our Souls Inspire","by":"Traditional, Veni Creator Spiritus","tr":"John Cosin","year":1662,"trad":["catholic","episcopal","christian"],"type":"hymn","occasion":["blessing","wedding"],"text":"Come, Holy Ghost, our souls inspire,\nAnd lighten with celestial fire.\nThou the anointing Spirit art,\nWho dost thy sevenfold gifts impart.\n\nThy blessed unction from above\nIs comfort, life, and fire of love.\nEnable with perpetual light\nThe dulness of our blinded sight.\n\nAnoint and cheer our soiled face\nWith the abundance of thy grace.\nKeep far our foes, give peace at home:\nWhere thou art guide, no ill can come.\n\nTeach us to know the Father, Son,\nAnd thee, of both, to be but One.\nThat through the ages all along,\nThis may be our endless song:\nPraise to thy eternal merit,\nFather, Son, and Holy Spirit.","translit":"Veni, Creator Spiritus","note":"The ancient hymn to the Holy Spirit, sung at ordinations, confirmations, and some weddings.","voice":"brian","source":{"name":"The Book of Common Prayer (1662): The Form and Manner of Ordering of Priests","url":"https://www.churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer"},"rights":"pd","pd":"Latin, ninth century; John Cosin translation 1627, printed in the Book of Common Prayer 1662; public domain.","denom":[]},{"id":"cath-litany-of-loreto","title":"The Litany of Loreto","by":"Traditional","year":1917,"trad":["catholic"],"type":"litany","occasion":["comfort","healing","dying"],"text":"Lord, have mercy. Christ, have mercy. Lord, have mercy.\nChrist, hear us. Christ, graciously hear us.\nGod the Father of heaven, have mercy on us.\nGod the Son, Redeemer of the world, have mercy on us.\nGod the Holy Ghost, have mercy on us.\nHoly Trinity, one God, have mercy on us.\n\nHoly Mary, pray for us.\nHoly Mother of God, pray for us.\nHoly Virgin of virgins, pray for us.\nMother of Christ, pray for us.\nMother of divine grace, pray for us.\nMother most amiable, pray for us.\nMother of good counsel, pray for us.\nMother of our Creator, pray for us.\nMother of our Saviour, pray for us.\nVirgin most prudent, pray for us.\nVirgin most merciful, pray for us.\nVirgin most faithful, pray for us.\nSeat of wisdom, pray for us.\nCause of our joy, pray for us.\nMystical rose, pray for us.\nHouse of gold, pray for us.\nArk of the covenant, pray for us.\nGate of heaven, pray for us.\nMorning star, pray for us.\nHealth of the sick, pray for us.\nRefuge of sinners, pray for us.\nComforter of the afflicted, pray for us.\nHelp of Christians, pray for us.\nQueen of Angels, pray for us.\nQueen of all Saints, pray for us.\nQueen of the most holy Rosary, pray for us.\nQueen of peace, pray for us.\n\nLamb of God, who takest away the sins of the world, spare us, O Lord.\nLamb of God, who takest away the sins of the world, graciously hear us, O Lord.\nLamb of God, who takest away the sins of the world, have mercy on us.\n\nLet us pray. Grant, we beseech Thee, O Lord God, that we Thy servants may enjoy perpetual health of mind and body;\nand by the glorious intercession of the Blessed Mary, ever Virgin,\nbe delivered from present sorrow, and enjoy eternal happiness. Through Christ our Lord. Amen.","note":"From the Litany of the Blessed Virgin Mary; Health of the sick and Comforter of the afflicted are well loved at a bedside.","voice":"jenny","source":{"name":"The Raccolta, English editions (1880s to 1910), Internet Archive","url":"https://archive.org/search?query=Raccolta+indulgenced+prayers"},"rights":"pd","pd":"Approved 1587; the line Queen of peace was added 1917; English form in prayer books; public domain. A selection of the titles.","denom":[]},{"id":"cath-litany-of-the-saints","title":"From the Litany of the Saints","by":"Traditional","year":1888,"trad":["catholic"],"type":"litany","occasion":["dying","funeral"],"text":"Holy Mary, pray for him.\nSaint Michael, pray for him.\nAll you holy Angels and Archangels, pray for him.\nSaint John the Baptist, pray for him.\nSaint Joseph, pray for him.\nAll you holy Patriarchs and Prophets, pray for him.\nSaint Peter and Saint Paul, pray for him.\nSaint Andrew, pray for him.\nSaint John, pray for him.\nAll you holy Apostles and Evangelists, pray for him.\nAll you holy Martyrs, pray for him.\nSaint Gregory, pray for him.\nSaint Augustine, pray for him.\nSaint Francis, pray for him.\nSaint Dominic, pray for him.\nAll you holy men and women, Saints of God, pray for him.\n\nBe merciful, spare him, O Lord.\nBe merciful, deliver him, O Lord.","note":"The Church's old prayer for one who is dying, calling the saints to gather near; say her or them as fits.","voice":"brian","source":{"name":"Rituale Romanum, Commendation of a Soul Departing, English editions, Internet Archive","url":"https://archive.org/search?query=Rituale+Romanum+commendation+of+a+soul+departing"},"rights":"pd","pd":"From the Commendation of a Departing Soul in the Roman Ritual, 1614; English form in prayer books; public domain. A shortened form.","denom":[]},{"id":"cath-litany-sacred-heart","title":"From the Litany of the Sacred Heart","by":"Traditional","year":1899,"trad":["catholic"],"type":"litany","occasion":["comfort","dying","peace"],"text":"Heart of Jesus, full of goodness and love, have mercy on us.\nHeart of Jesus, patient and most merciful, have mercy on us.\nHeart of Jesus, source of all consolation, have mercy on us.\nHeart of Jesus, our life and resurrection, have mercy on us.\nHeart of Jesus, our peace and our reconciliation, have mercy on us.\nHeart of Jesus, salvation of those who trust in Thee, have mercy on us.\nHeart of Jesus, hope of those who die in Thee, have mercy on us.\nHeart of Jesus, delight of all the Saints, have mercy on us.\n\nV. Jesus, meek and humble of heart.\nR. Make our hearts like unto Thine.","note":"A few of the litany's lines, chosen for the bedside; hope of those who die in Thee comforts many families.","voice":"jenny","source":{"name":"The Raccolta, English editions (1880s to 1910), Internet Archive","url":"https://archive.org/search?query=Raccolta+indulgenced+prayers"},"rights":"pd","pd":"Approved for the whole Church by Pope Leo XIII in 1899; English form in prayer books; public domain. A selection.","denom":[]},{"id":"cath-in-paradisum","title":"May the Angels Lead You into Paradise","by":"Traditional, In Paradisum","year":1888,"trad":["catholic","christian"],"denom":["requiem"],"type":"prayer","occasion":["funeral","dying","grief"],"text":"May the angels lead thee into paradise;\nmay the martyrs receive thee at thy coming,\nand lead thee into the holy city Jerusalem.\nMay the choir of angels receive thee,\nand with Lazarus, who once was poor,\nmayest thou have eternal rest.","translit":"In paradisum deducant te angeli","note":"Sung or said as the body is carried from the church at the end of a Catholic funeral.","voice":"brian","source":{"name":"A Manual of Prayers for the Use of the Catholic Laity (1888), Internet Archive","url":"https://archive.org/search?query=%22Manual+of+Prayers+for+the+Use+of+the+Catholic+Laity%22"},"rights":"pd","pd":"From the Latin funeral rite, early medieval; English form in prayer books by the 1800s; public domain."},{"id":"cath-subvenite","title":"Come to Assist Him, You Saints of God","by":"Traditional, Subvenite","year":1888,"trad":["catholic"],"denom":["requiem"],"type":"prayer","occasion":["dying","funeral"],"text":"Come to his assistance, ye Saints of God;\ncome forth to meet him, ye Angels of the Lord,\nreceiving his soul, offering it in the sight of the Most High.\n\nMay Christ receive thee, who hath called thee,\nand may the Angels conduct thee into Abraham's bosom.\n\nEternal rest give unto him, O Lord,\nand let perpetual light shine upon him.","translit":"Subvenite, Sancti Dei","note":"Prayed right after death, at the bedside, and at the final commendation of a funeral; say her as fits.","voice":"jenny","source":{"name":"A Manual of Prayers for the Use of the Catholic Laity (1888), Internet Archive","url":"https://archive.org/search?query=%22Manual+of+Prayers+for+the+Use+of+the+Catholic+Laity%22"},"rights":"pd","pd":"From the Latin rite for the dead, early medieval; English form in prayer books by the 1800s; public domain."},{"id":"cath-proficiscere","title":"Go Forth, Christian Soul","by":"Traditional, Proficiscere","year":1888,"trad":["catholic"],"denom":["requiem"],"type":"prayer","occasion":["dying"],"text":"Go forth, O Christian soul, out of this world,\nin the name of God the Father Almighty, who created thee;\nin the name of Jesus Christ, the Son of the living God, who suffered for thee;\nin the name of the Holy Ghost, who was poured forth upon thee;\nin the name of the Angels and Archangels;\nin the name of the Patriarchs and Prophets;\nin the name of the holy Apostles and Evangelists;\nin the name of the holy Martyrs, Confessors, and Virgins,\nand of all the Saints of God.\nMay thy place be this day in peace, and thy abode in holy Sion.\nThrough the same Christ our Lord. Amen.","translit":"Proficiscere, anima christiana, de hoc mundo","note":"The Church's ancient blessing for the moment of death, said as the last breaths come.","voice":"brian","source":{"name":"Rituale Romanum, Commendation of a Soul Departing, English editions, Internet Archive","url":"https://archive.org/search?query=Rituale+Romanum+commendation+of+a+soul+departing"},"rights":"pd","pd":"From the Roman Ritual, 1614, and earlier; English form in prayer books by the 1800s; public domain."},{"id":"cath-gerontius-go-forth","title":"Go Forth upon Thy Journey","by":"John Henry Newman","year":1865,"trad":["catholic","christian"],"type":"poem","occasion":["dying"],"text":"Proficiscere, anima Christiana, de hoc mundo!\nGo forth upon thy journey, Christian soul!\nGo from this world! Go, in the name of God\nThe Omnipotent Father, who created thee!\nGo, in the name of Jesus Christ, our Lord,\nSon of the living God, who bled for thee!\nGo, in the name of the Holy Spirit, who\nHath been poured out on thee! Go, in the name\nOf Angels and Archangels; in the name\nOf Thrones and Dominations; in the name\nOf Princedoms and of Powers; and in the name\nOf Cherubim and Seraphim, go forth!","note":"The priest's words at the deathbed in The Dream of Gerontius, the old prayer set as poetry.","voice":"jenny","source":{"name":"John Henry Newman, The Dream of Gerontius (1865), Newman Reader","url":"https://www.newmanreader.org/works/verses/gerontius.html"},"rights":"pd","pd":"Published 1865; Newman died 1890; public domain.","denom":[]},{"id":"cath-gerontius-softly","title":"Softly and Gently","by":"John Henry Newman","year":1865,"trad":["catholic","christian","all"],"type":"poem","occasion":["dying","funeral","grief"],"text":"Softly and gently, dearly ransomed soul,\nIn my most loving arms I now enfold thee,\nAnd, o'er the penal waters, as they roll,\nI poise thee, and I lower thee, and hold thee.\n\nAnd carefully I dip thee in the lake,\nAnd thou, without a sob or a resistance,\nDost through the flood thy rapid passage take,\nSinking deep, deeper, into the dim distance.\n\nAngels, to whom the willing task is given,\nShall tend, and nurse, and lull thee, as thou liest;\nAnd Masses on the earth, and prayers in heaven,\nShall aid thee at the Throne of the Most Highest.\n\nFarewell, but not for ever! brother dear,\nBe brave and patient on thy bed of sorrow;\nSwiftly shall pass thy night of trial here,\nAnd I will come and wake thee on the morrow.","note":"The guardian angel's farewell from The Dream of Gerontius, tender at a vigil or a funeral; say sister dear as fits.","voice":"brian","source":{"name":"John Henry Newman, The Dream of Gerontius (1865), Newman Reader","url":"https://www.newmanreader.org/works/verses/gerontius.html"},"rights":"pd","pd":"Published 1865; Newman died 1890; public domain.","denom":[]},{"id":"cath-dies-irae","title":"From the Dies Irae","by":"Traditional, attributed to Thomas of Celano","tr":"William Josiah Irons","year":1848,"trad":["catholic"],"denom":["requiem"],"type":"hymn","occasion":["funeral","forgiveness"],"text":"Think, kind Jesu! my salvation\nCaused Thy wondrous Incarnation;\nLeave me not to reprobation!\n\nFaint and weary Thou hast sought me,\nOn the Cross of suffering bought me;\nShall such grace be vainly brought me?\n\nThou the sinful woman savest;\nThou the dying thief forgavest;\nAnd to me a hope vouchsafest.\n\nLord, all pitying, Jesu blest,\nGrant them Thine eternal rest. Amen.","translit":"Pie Iesu Domine, dona eis requiem","note":"The mercy verses of the old Requiem sequence, a plea for grace sung at funerals for centuries.","voice":"jenny","source":{"name":"Hymnary.org","url":"https://hymnary.org/search?qu=Day+of+wrath+O+day+of+mourning"},"rights":"pd","pd":"Latin, thirteenth century; William Josiah Irons translation 1848, Irons died 1883; public domain."},{"id":"cath-de-profundis","title":"Out of the Depths (Psalm 129)","by":"Douay-Rheims Bible, Psalm 129","year":1752,"trad":["catholic","christian"],"denom":["requiem"],"type":"scripture","occasion":["grief","funeral","forgiveness","hope"],"text":"Out of the depths I have cried to thee, O Lord:\nLord, hear my voice. Let thy ears be attentive to the voice of my supplication.\nIf thou, O Lord, wilt mark iniquities: Lord, who shall stand it.\nFor with thee there is merciful forgiveness: and by reason of thy law, I have waited for thee, O Lord. My soul hath relied on his word:\nmy soul hath hoped in the Lord.\nFrom the morning watch even until night, let Israel hope in the Lord.\nBecause with the Lord there is mercy: and with him plentiful redemption.\nAnd he shall redeem Israel from all his iniquities.","translit":"De profundis clamavi ad te, Domine","note":"The De Profundis, the Church's psalm for the dead, prayed at wakes and on anniversaries (Psalm 130 in most Bibles).","voice":"brian","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-for-the-faithful-departed","title":"For All the Faithful Departed","by":"Traditional, Roman Missal","year":1888,"trad":["catholic"],"denom":["requiem"],"type":"prayer","occasion":["grief","funeral"],"text":"O God, the Creator and Redeemer of all the faithful,\ngrant to the souls of Thy servants departed the remission of all their sins;\nthat through pious supplications they may obtain the pardon which they have always desired.\nWho livest and reignest, world without end. Amen.","translit":"Fidelium, Deus, omnium Conditor et Redemptor","note":"The collect for All Souls, said on November 2 and whenever a family remembers its dead.","voice":"jenny","source":{"name":"A Manual of Prayers for the Use of the Catholic Laity (1888), Internet Archive","url":"https://archive.org/search?query=%22Manual+of+Prayers+for+the+Use+of+the+Catholic+Laity%22"},"rights":"pd","pd":"Collect Fidelium Deus from the Roman Missal; English form in prayer books by the 1800s; public domain."},{"id":"cath-incline-thine-ear","title":"For One Who Has Died","by":"Traditional, Roman Missal","year":1888,"trad":["catholic"],"denom":["requiem"],"type":"prayer","occasion":["funeral","grief"],"text":"Incline Thine ear, O Lord, unto our prayers,\nwherein we humbly pray Thee to show Thy mercy upon the soul of Thy servant,\nwhom Thou hast commanded to pass out of this world;\nthat Thou wouldst place him in the region of peace and light,\nand bid him be a partaker with Thy Saints.\nThrough Christ our Lord. Amen.","note":"A collect for one person who has died; say the name, and her as fits.","voice":"brian","source":{"name":"A Manual of Prayers for the Use of the Catholic Laity (1888), Internet Archive","url":"https://archive.org/search?query=%22Manual+of+Prayers+for+the+Use+of+the+Catholic+Laity%22"},"rights":"pd","pd":"Collect Inclina, Domine from the Roman Missal; English form in prayer books by the 1800s; public domain."},{"id":"cath-holy-and-wholesome","title":"A Holy and Wholesome Thought","by":"Douay-Rheims Bible, 2 Machabees 12:46","year":1752,"trad":["catholic"],"type":"scripture","occasion":["grief","funeral"],"text":"It is therefore a holy and wholesome thought to pray for the dead, that they may be loosed from sins.","note":"The verse behind the Catholic custom of praying for those who have died.","voice":"jenny","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain.","denom":[]},{"id":"cath-wisdom-3","title":"The Souls of the Just (Wisdom 3)","by":"Douay-Rheims Bible, Wisdom 3:1 to 3, 9","year":1752,"trad":["catholic","episcopal","orthodox"],"type":"scripture","occasion":["funeral","grief","hope"],"text":"But the souls of the just are in the hand of God, and the torment of death shall not touch them.\nIn the sight of the unwise they seemed to die: and their departure was taken for misery:\nAnd their going away from us, for utter destruction: but they are in peace.\n\nThey that trust in him shall understand the truth: and they that are faithful in love, shall rest in him: for grace and peace are to his elect.","note":"One of the best loved readings at Catholic funerals.","voice":"brian","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain.","denom":[]},{"id":"cath-john-11","title":"I Am the Resurrection (John 11)","by":"Douay-Rheims Bible, John 11:25 to 26","year":1752,"trad":["catholic"],"type":"scripture","occasion":["funeral","hope","dying"],"text":"Jesus said to her: I am the resurrection and the life: he that believeth in me, although he be dead, shall live:\nAnd every one that liveth and believeth in me shall not die for ever. Believest thou this?","note":"Spoken to Martha at her brother's grave, and read at almost every Christian funeral.","voice":"jenny","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain.","denom":[]},{"id":"cath-beatitudes","title":"The Beatitudes","by":"Douay-Rheims Bible, Matthew 5:3 to 10","year":1752,"trad":["catholic","christian"],"type":"scripture","occasion":["funeral","comfort","grief"],"text":"Blessed are the poor in spirit: for theirs is the kingdom of heaven.\nBlessed are the meek: for they shall possess the land.\nBlessed are they that mourn: for they shall be comforted.\nBlessed are they that hunger and thirst after justice: for they shall have their fill.\nBlessed are the merciful: for they shall obtain mercy.\nBlessed are the clean of heart: they shall see God.\nBlessed are the peacemakers: for they shall be called the children of God.\nBlessed are they that suffer persecution for justice' sake: for theirs is the kingdom of heaven.","note":"A favorite funeral Gospel, honoring a life lived with mercy and peace.","voice":"brian","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain.","denom":[]},{"id":"cath-charity-1-cor-13","title":"Charity Is Patient (1 Corinthians 13)","by":"Douay-Rheims Bible, 1 Corinthians 13:4 to 8, 13","year":1752,"trad":["catholic"],"type":"scripture","occasion":["wedding","funeral"],"text":"Charity is patient, is kind: charity envieth not, dealeth not perversely, is not puffed up,\nIs not ambitious, seeketh not her own, is not provoked to anger, thinketh no evil:\nRejoiceth not in iniquity, but rejoiceth with the truth:\nBeareth all things, believeth all things, hopeth all things, endureth all things.\nCharity never falleth away: whether prophecies shall be made void or tongues shall cease or knowledge shall be destroyed.\n\nAnd now there remain faith, hope, and charity, these three: but the greatest of these is charity.","note":"The love chapter in the Catholic Douay wording, read at weddings and at funerals of a loving life.","voice":"jenny","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain.","denom":[]},{"id":"cath-ruth-whither","title":"Whither Thou Shalt Go (Ruth 1)","by":"Douay-Rheims Bible, Ruth 1:16 to 17","year":1752,"trad":["catholic"],"type":"scripture","occasion":["wedding","home"],"text":"She answered: Be not against me, to desire that I should leave thee and depart: for whithersoever thou shalt go, I will go: and where thou shalt dwell, I also will dwell. Thy people shall be my people, and thy God my God.\nThe land that shall receive thee dying, in the same will I die: and there will I be buried. The Lord do so and so to me, and add more also, if aught but death part me and thee.","note":"Ruth's promise to Naomi, read at weddings and to honor lifelong loyalty.","voice":"brian","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain.","denom":[]},{"id":"cath-works-of-mercy","title":"The Works of Mercy","by":"Traditional","year":1891,"trad":["catholic","christian"],"type":"reflection","occasion":["funeral","daily"],"text":"The corporal works of mercy are:\nto feed the hungry;\nto give drink to the thirsty;\nto clothe the naked;\nto ransom the captive;\nto harbor the harbourless;\nto visit the sick;\nand to bury the dead.\n\nThe spiritual works of mercy are:\nto admonish the sinner;\nto instruct the ignorant;\nto counsel the doubtful;\nto comfort the sorrowful;\nto bear wrongs patiently;\nto forgive all injuries;\nand to pray for the living and the dead.","note":"A way to honor a life spent serving others, read at a funeral or a volunteer's memorial.","voice":"jenny","source":{"name":"Baltimore Catechism (1891), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/search/?query=baltimore+catechism"},"rights":"pd","pd":"From the Baltimore Catechism, 1891, rooted in Matthew 25; public domain.","denom":[]},{"id":"cath-stations-of-the-cross","title":"The Stations of the Cross","by":"Traditional","year":1888,"trad":["catholic"],"type":"litany","occasion":["season","comfort","grief"],"text":"We adore Thee, O Christ, and we bless Thee,\nbecause by Thy holy Cross Thou hast redeemed the world.\n\nThe First Station: Jesus is condemned to death.\nThe Second Station: Jesus carries His Cross.\nThe Third Station: Jesus falls the first time.\nThe Fourth Station: Jesus meets His Mother.\nThe Fifth Station: Simon of Cyrene helps Jesus carry the Cross.\nThe Sixth Station: Veronica wipes the face of Jesus.\nThe Seventh Station: Jesus falls the second time.\nThe Eighth Station: Jesus speaks to the women of Jerusalem.\nThe Ninth Station: Jesus falls the third time.\nThe Tenth Station: Jesus is stripped of His garments.\nThe Eleventh Station: Jesus is nailed to the Cross.\nThe Twelfth Station: Jesus dies on the Cross.\nThe Thirteenth Station: Jesus is taken down from the Cross.\nThe Fourteenth Station: Jesus is laid in the tomb.\n\nWe adore Thee, O Christ, and we bless Thee,\nbecause by Thy holy Cross Thou hast redeemed the world.","translit":"Adoramus te, Christe, et benedicimus tibi","note":"Walked in church on the Fridays of Lent; the versicle is said at each station. Many who suffer find company in it.","voice":"brian","source":{"name":"A Manual of Prayers for the Use of the Catholic Laity (1888), Internet Archive","url":"https://archive.org/search?query=%22Manual+of+Prayers+for+the+Use+of+the+Catholic+Laity%22"},"rights":"pd","pd":"The fourteen stations were fixed in the 1700s; English forms in prayer books by the 1800s; public domain.","denom":[]},{"id":"cath-priestly-blessing","title":"May Almighty God Bless You","by":"Traditional","year":1888,"trad":["catholic","christian"],"type":"blessing","occasion":["blessing","funeral","wedding"],"text":"May the blessing of Almighty God,\nthe Father, the Son, and the Holy Ghost,\ndescend upon you and remain with you always. Amen.","translit":"Benedicat vos omnipotens Deus","note":"A closing blessing for a gathering, a home, or a family leaving the graveside.","voice":"jenny","source":{"name":"A Manual of Prayers for the Use of the Catholic Laity (1888), Internet Archive","url":"https://archive.org/search?query=%22Manual+of+Prayers+for+the+Use+of+the+Catholic+Laity%22"},"rights":"pd","pd":"Traditional blessing; English form in prayer books by the 1800s; public domain.","denom":[]},{"id":"cath-vigil-with-the-rosary","title":"A Blessing for a Rosary Vigil","by":"Grow With Grounded","year":2026,"trad":["catholic"],"denom":["rosary"],"type":"blessing","occasion":["dying","comfort"],"text":"Bead by bead, we keep watch with you.\nMary, who stood near her Son to the last, stands near you now.\nEvery Hail Mary is a hand held.\nRest in the love that surrounds you.","note":"Grounded words to open or close a family's Rosary at the bedside.","voice":"brian","source":{"name":"Grow With Grounded, written for the Grounded Readings Library (2026)","url":""},"rights":"grounded","pd":"Grounded's own words."},{"id":"cath-blessing-for-a-catholic-home","title":"A Blessing for a Catholic Home","by":"Grow With Grounded","year":2026,"trad":["catholic"],"type":"blessing","occasion":["home","blessing"],"text":"Holy Family of Nazareth, make this house a home like yours.\nMay its table be full of good food and laughter,\nits doors open to friends and strangers,\nits nights full of peace,\nand its rooms full of the quiet presence of God.","note":"Grounded words for a house blessing, alongside holy water and the family's own prayers.","voice":"jenny","source":{"name":"Grow With Grounded, written for the Grounded Readings Library (2026)","url":""},"rights":"grounded","pd":"Grounded's own words.","denom":[]},{"id":"cath-o-heavenly-king","title":"O Heavenly King","by":"Traditional","year":1906,"trad":["orthodox"],"denom":["eastern"],"type":"prayer","occasion":["morning","blessing","daily"],"text":"O Heavenly King, the Comforter, the Spirit of Truth,\nwho art in all places and fillest all things;\nthe Treasury of good things and Giver of life:\ncome and dwell in us, and cleanse us from every stain,\nand save our souls, O Good One.","translit":"Vasilefs ouranie, Paraklite","note":"The prayer to the Holy Spirit that opens nearly every Orthodox service and the day's prayers.","voice":"jenny","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic Church (1906), Internet Archive","url":"https://archive.org/search?query=Hapgood+Service+Book+Holy+Orthodox-Catholic+Apostolic+Church"},"rights":"pd","pd":"Ancient liturgical text; the English follows the older public domain renderings (Hapgood 1906); confirm wording against Hapgood."},{"id":"cath-trisagion","title":"The Trisagion","by":"Traditional","year":1906,"trad":["orthodox","catholic","oriental"],"denom":["eastern"],"type":"chant","occasion":["daily","funeral","dying"],"text":"Holy God, Holy Mighty, Holy Immortal, have mercy on us.\nHoly God, Holy Mighty, Holy Immortal, have mercy on us.\nHoly God, Holy Mighty, Holy Immortal, have mercy on us.\n\nGlory to the Father, and to the Son, and to the Holy Spirit,\nnow and ever, and unto ages of ages. Amen.\n\nAll holy Trinity, have mercy on us.\nO Lord, cleanse us from our sins.\nO Master, pardon our transgressions.\nO Holy One, visit and heal our infirmities, for Thy Name's sake.\nLord, have mercy. Lord, have mercy. Lord, have mercy.","translit":"Agios o Theos, Agios Ischyros, Agios Athanatos, eleison imas","note":"The thrice holy hymn, sung in the services of every Eastern church, and the heart of the short memorial at the grave.","voice":"brian","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic Church (1906), Internet Archive","url":"https://archive.org/search?query=Hapgood+Service+Book+Holy+Orthodox-Catholic+Apostolic+Church"},"rights":"pd","pd":"Ancient liturgical text; the English follows the older public domain renderings (Hapgood 1906); confirm wording against Hapgood."},{"id":"cath-with-the-saints-give-rest","title":"With the Saints Give Rest","by":"Traditional, Kontakion for the Departed","year":1906,"trad":["orthodox","all"],"denom":["eastern"],"type":"chant","occasion":["funeral","grief","dying"],"text":"With the Saints give rest, O Christ, to the soul of Thy servant,\nwhere there is neither sickness, nor sorrow, nor sighing,\nbut life everlasting.\n\nThou only art immortal, who hast created and fashioned man;\nand we are mortal, formed of the earth, and unto earth shall we return,\nas Thou didst command when Thou madest me, saying unto me:\nDust thou art, and unto dust shalt thou return;\nwhither all we mortals are going,\nmaking of our funeral dirge the song: Alleluia, alleluia, alleluia.","translit":"Meta ton agion anapafson","note":"The kontakion and ikos of the Orthodox funeral; even at the grave we make our song: Alleluia.","voice":"jenny","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic Church (1906), Internet Archive","url":"https://archive.org/search?query=Hapgood+Service+Book+Holy+Orthodox-Catholic+Apostolic+Church"},"rights":"pd","pd":"Ancient liturgical text; the English follows the older public domain renderings (Hapgood 1906); confirm wording against Hapgood."},{"id":"cath-god-of-spirits","title":"O God of Spirits and of All Flesh","by":"Traditional","year":1906,"trad":["orthodox"],"denom":["eastern"],"type":"prayer","occasion":["funeral","grief","dying"],"text":"O God of spirits and of all flesh, who hast trampled down death,\nand overthrown the devil, and given life to Thy world:\nDo Thou, the same Lord, give rest to the soul of Thy departed servant,\nin a place of brightness, a place of verdure, a place of repose,\nwhence all sickness, sorrow, and sighing have fled away.\nPardon every transgression which he hath committed, whether by word, or deed, or thought.\nFor Thou art a good God, and lovest mankind.\n\nFor Thou art the Resurrection, and the Life, and the Repose of Thy servant who is fallen asleep,\nO Christ our God, and unto Thee we ascribe glory,\ntogether with Thy Father, who is from everlasting,\nand Thine all holy, and good, and life giving Spirit,\nnow, and ever, and unto ages of ages. Amen.","note":"The central prayer of the Panikhida and the Orthodox funeral, prayed at the third, ninth, and fortieth day; say her as fits.","voice":"brian","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic Church (1906), Internet Archive","url":"https://archive.org/search?query=Hapgood+Service+Book+Holy+Orthodox-Catholic+Apostolic+Church"},"rights":"pd","pd":"Ancient liturgical text; the English follows the older public domain renderings (Hapgood 1906); confirm wording against Hapgood."},{"id":"cath-memory-eternal","title":"Memory Eternal","by":"Traditional","year":1906,"trad":["orthodox","oriental"],"denom":["eastern"],"type":"chant","occasion":["funeral","grief"],"text":"Grant, O Lord, rest eternal to the soul of Thy servant who has fallen asleep,\nand make his memory to be eternal.\n\nMemory eternal!\nMemory eternal!\nMemory eternal!","translit":"Eonia i mnimi","note":"Sung three times at the close of every Orthodox funeral and memorial; say the name, and her as fits.","voice":"jenny","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic Church (1906), Internet Archive","url":"https://archive.org/search?query=Hapgood+Service+Book+Holy+Orthodox-Catholic+Apostolic+Church"},"rights":"pd","pd":"Ancient liturgical text; the English follows the older public domain renderings (Hapgood 1906); confirm wording against Hapgood."},{"id":"cath-souls-of-the-righteous","title":"With the Souls of the Righteous","by":"Traditional, Troparion for the Departed","year":1906,"trad":["orthodox"],"denom":["eastern"],"type":"chant","occasion":["funeral","grief"],"text":"With the souls of the righteous dead, give rest, O Saviour, to the soul of Thy servant,\npreserving it in that life of blessedness which is with Thee,\nO Thou who lovest mankind.\n\nIn the place of Thy rest, O Lord, where all Thy Saints repose,\ngive rest also to the soul of Thy servant,\nfor Thou alone lovest mankind.","note":"Sung at the memorial service for the departed.","voice":"brian","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic Church (1906), Internet Archive","url":"https://archive.org/search?query=Hapgood+Service+Book+Holy+Orthodox-Catholic+Apostolic+Church"},"rights":"pd","pd":"Ancient liturgical text; the English follows the older public domain renderings (Hapgood 1906); confirm wording against Hapgood."},{"id":"cath-christ-is-risen","title":"Christ Is Risen","by":"Traditional, Paschal Troparion","year":1906,"trad":["orthodox","oriental","all"],"denom":["eastern"],"type":"chant","occasion":["season","hope","funeral","celebration"],"text":"Christ is risen from the dead,\ntrampling down death by death,\nand upon those in the tombs bestowing life.","translit":"Christos anesti ek nekron","note":"The Easter hymn, sung over and over for forty days and at Orthodox funerals in the Easter season.","voice":"jenny","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic Church (1906), Internet Archive","url":"https://archive.org/search?query=Hapgood+Service+Book+Holy+Orthodox-Catholic+Apostolic+Church"},"rights":"pd","pd":"Ancient liturgical text; the English follows the older public domain renderings (Hapgood 1906); confirm wording against Hapgood."},{"id":"cath-paschal-homily","title":"From the Paschal Homily","by":"Saint John Chrysostom","year":1906,"trad":["orthodox"],"denom":["eastern"],"type":"reflection","occasion":["season","hope","celebration","funeral"],"text":"Let no one fear death, for the Saviour's death has set us free.\n\nO Death, where is thy sting? O Hell, where is thy victory?\nChrist is risen, and thou art overthrown.\nChrist is risen, and the demons are fallen.\nChrist is risen, and the angels rejoice.\nChrist is risen, and life reigns.\nChrist is risen, and not one dead remains in the grave.\n\nFor Christ, being risen from the dead, is become the first fruits of them that slept.\nTo Him be glory and dominion unto ages of ages. Amen.","note":"Read aloud at every Orthodox Easter midnight service; the closing lines ring with hope at any funeral.","voice":"brian","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic Church (1906), Internet Archive","url":"https://archive.org/search?query=Hapgood+Service+Book+Holy+Orthodox-Catholic+Apostolic+Church"},"rights":"pd","pd":"Written by Chrysostom (died 407); English as in the older public domain service books; confirm wording against Hapgood 1906."},{"id":"cath-prayer-of-saint-ephrem","title":"The Prayer of Saint Ephrem","by":"Saint Ephrem the Syrian","year":1906,"trad":["orthodox","oriental"],"denom":["eastern","syriac"],"type":"prayer","occasion":["season","forgiveness","daily"],"text":"O Lord and Master of my life,\ntake from me the spirit of sloth, despair, lust of power, and idle talk.\n\nBut give rather the spirit of chastity, humility, patience, and love to Thy servant.\n\nYea, O Lord and King, grant me to see my own errors and not to judge my brother;\nfor blessed art Thou unto ages of ages. Amen.","note":"Prayed with bows throughout Great Lent; a whole spiritual life in three lines.","voice":"jenny","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic Church (1906), Internet Archive","url":"https://archive.org/search?query=Hapgood+Service+Book+Holy+Orthodox-Catholic+Apostolic+Church"},"rights":"pd","pd":"Written by Ephrem (died 373); English as in older service books; confirm wording against Hapgood 1906."},{"id":"cath-glory-for-all-things","title":"Glory to God for All Things","by":"Saint John Chrysostom","year":1906,"trad":["orthodox","all"],"denom":["eastern"],"type":"reflection","occasion":["dying","gratitude"],"text":"Glory to God for all things.","translit":"Doxa to Theo panton eneken","note":"The last words of Saint John Chrysostom as he died in exile in 407; a whole life of gratitude in five words.","voice":"brian","source":{"name":"Palladius, Dialogue on the Life of St. John Chrysostom, Internet Archive","url":"https://archive.org/search?query=Palladius+dialogue+life+of+St.+John+Chrysostom"},"rights":"pd","pd":"Last words recorded about 408; a short traditional saying; public domain."},{"id":"cath-axion-estin","title":"It Is Truly Meet","by":"Traditional","year":1906,"trad":["orthodox"],"denom":["eastern"],"type":"chant","occasion":["daily","gratitude"],"text":"It is truly meet to bless thee, O Theotokos,\never blessed and most pure, and the Mother of our God.\nMore honourable than the Cherubim,\nand beyond compare more glorious than the Seraphim,\nwho without corruption gavest birth to God the Word,\ntrue Theotokos, we magnify thee.","translit":"Axion estin os alithos","note":"The hymn to the Mother of God sung at the Divine Liturgy and at the close of many prayers.","voice":"jenny","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic Church (1906), Internet Archive","url":"https://archive.org/search?query=Hapgood+Service+Book+Holy+Orthodox-Catholic+Apostolic+Church"},"rights":"pd","pd":"Ancient liturgical text; the English follows the older public domain renderings (Hapgood 1906); confirm wording against Hapgood."},{"id":"cath-into-thy-hands-orthodox","title":"Into Thy Hands","by":"Traditional, Orthodox Evening Prayers","year":1906,"trad":["orthodox"],"denom":["eastern"],"type":"prayer","occasion":["evening","dying","peace"],"text":"Into Thy hands, O Lord Jesus Christ, my God, I commend my spirit.\nDo Thou bless me, have mercy on me, and grant me life eternal. Amen.","note":"The last of the Orthodox evening prayers, said before sleep and at the last breath.","voice":"brian","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic Church (1906), Internet Archive","url":"https://archive.org/search?query=Hapgood+Service+Book+Holy+Orthodox-Catholic+Apostolic+Church"},"rights":"pd","pd":"Ancient liturgical text; the English follows the older public domain renderings (Hapgood 1906); confirm wording against Hapgood."},{"id":"cath-crowning","title":"The Crowning","by":"Traditional, Orthodox Service of Marriage","year":1906,"trad":["orthodox"],"denom":["eastern"],"type":"blessing","occasion":["wedding","celebration"],"text":"The servant of God is crowned unto the handmaid of God,\nin the Name of the Father, and of the Son, and of the Holy Spirit.\n\nThe handmaid of God is crowned unto the servant of God,\nin the Name of the Father, and of the Son, and of the Holy Spirit.\n\nO Lord our God, crown them with glory and honour.","note":"The heart of the Orthodox wedding, when crowns are placed on the couple; say their names.","voice":"jenny","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic Church (1906), Internet Archive","url":"https://archive.org/search?query=Hapgood+Service+Book+Holy+Orthodox-Catholic+Apostolic+Church"},"rights":"pd","pd":"Ancient liturgical text; the English follows the older public domain renderings (Hapgood 1906); confirm wording against Hapgood."},{"id":"cath-way-of-a-pilgrim","title":"From The Way of a Pilgrim","by":"Anonymous Russian pilgrim","tr":"R. M. French","year":1930,"trad":["orthodox","christian","sbnr"],"denom":["eastern","russian"],"type":"story","occasion":["daily","peace"],"text":"By the grace of God I am a Christian man, by my actions a great sinner, and by calling a homeless wanderer of the humblest birth who roams from place to place. My worldly goods are a knapsack with some dried bread in it on my back, and in my breast pocket a Bible. And that is all.","note":"The opening of the Russian classic that brought the Jesus Prayer to readers around the world.","voice":"brian","source":{"name":"The Way of a Pilgrim, translated by R. M. French (1930), Internet Archive","url":"https://archive.org/search?query=%22Way+of+a+Pilgrim%22+French+1930"},"rights":"pd","pd":"Russian, 1880s; R. M. French translation published 1930, public domain in the United States since January 1, 2026; confirm the 1930 wording."},{"id":"cath-eyes-of-all","title":"The Eyes of All (Grace)","by":"King James Version, Psalm 145:15 to 16","year":1611,"trad":["orthodox","christian"],"denom":["eastern"],"type":"scripture","occasion":["daily","gratitude","home"],"text":"The eyes of all wait upon thee; and thou givest them their meat in due season.\nThou openest thine hand, and satisfiest the desire of every living thing.","note":"The verse many Orthodox and Anglican families sing or say as grace before meals.","voice":"jenny","source":{"name":"King James Bible (1611), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/10"},"rights":"pd","pd":"King James Version, 1611; public domain in the United States."},{"id":"cath-psalm-104-vespers","title":"O Lord My God, Thou Art Very Great (Psalm 104)","by":"King James Version, Psalm 104:1 to 2, 10 to 12, 24, 33","year":1611,"trad":["orthodox","christian","nature"],"denom":["eastern"],"type":"scripture","occasion":["nature","evening","gratitude"],"text":"Bless the Lord, O my soul. O Lord my God, thou art very great; thou art clothed with honour and majesty.\nWho coverest thyself with light as with a garment: who stretchest out the heavens like a curtain:\n\nHe sendeth the springs into the valleys, which run among the hills.\nThey give drink to every beast of the field: the wild asses quench their thirst.\nBy them shall the fowls of the heaven have their habitation, which sing among the branches.\n\nO Lord, how manifold are thy works! in wisdom hast thou made them all: the earth is full of thy riches.\n\nI will sing unto the Lord as long as I live: I will sing praise to my God while I have my being.","note":"The creation psalm that opens Orthodox Vespers every evening; lovely for a nature lover.","voice":"brian","source":{"name":"King James Bible (1611), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/10"},"rights":"pd","pd":"King James Version, 1611; public domain in the United States."},{"id":"cath-phos-hilaron","title":"Hail, Gladdening Light","by":"Traditional Greek hymn, third century","tr":"John Keble","year":1834,"trad":["orthodox","episcopal","christian"],"denom":["eastern"],"type":"hymn","occasion":["evening","peace"],"text":"Hail, gladdening Light, of His pure glory poured\nWho is the immortal Father, heavenly, blest,\nHoliest of Holies, Jesus Christ our Lord!\n\nNow we are come to the sun's hour of rest,\nThe lights of evening round us shine,\nWe hymn the Father, Son, and Holy Spirit divine.\n\nWorthiest art Thou at all times to be sung\nWith undefiled tongue,\nSon of our God, giver of life, alone:\nTherefore in all the world, Thy glories, Lord, they own.","translit":"Phos hilaron","note":"The oldest Christian hymn still sung, at the lighting of the evening lamps; gentle at dusk at a bedside.","voice":"jenny","source":{"name":"Hymnary.org","url":"https://hymnary.org/search?qu=Hail+gladdening+light+of+his+pure+glory+poured"},"rights":"pd","pd":"Greek Phos Hilaron, third century; John Keble translation 1834, Keble died 1866; public domain."},{"id":"cath-blessing-for-the-fortieth-day","title":"A Blessing for the Fortieth Day","by":"Grow With Grounded","year":2026,"trad":["orthodox"],"denom":["eastern"],"type":"blessing","occasion":["grief","funeral"],"text":"Forty days of tears and remembering.\nForty days of candles lit and prayers sung.\nMay the one we love rest among the saints, in a place of light.\nMay we who remain carry their memory with joy.\nMemory eternal.","note":"Grounded words for a family gathering on the fortieth day after a death, alongside the Church's own memorial.","voice":"brian","source":{"name":"Grow With Grounded, written for the Grounded Readings Library (2026)","url":""},"rights":"grounded","pd":"Grounded's own words."},{"id":"cath-blessing-for-an-icon-corner","title":"A Blessing for the Icon Corner","by":"Grow With Grounded","year":2026,"trad":["orthodox"],"denom":["eastern"],"type":"blessing","occasion":["home","daily"],"text":"Here, in the corner of our home, the saints keep watch with us.\nMay the lamp burn steady.\nMay our prayers rise like incense.\nMay every face that passes here find a little more peace.","note":"Grounded words for setting up or renewing a home's icon corner.","voice":"jenny","source":{"name":"Grow With Grounded, written for the Grounded Readings Library (2026)","url":""},"rights":"grounded","pd":"Grounded's own words."},{"id":"cath-ethiopia-stretch-out","title":"Ethiopia Shall Stretch Out Her Hands (Psalm 68)","by":"King James Version, Psalm 68:31 to 32","year":1611,"trad":["oriental","blackchurch"],"denom":["ethiopian"],"type":"scripture","occasion":["hope","celebration"],"text":"Princes shall come out of Egypt; Ethiopia shall soon stretch out her hands unto God.\nSing unto God, ye kingdoms of the earth; O sing praises unto the Lord; Selah:","note":"A verse treasured by the Ethiopian Orthodox Tewahedo Church and by the African American church as a promise for Africa's people.","voice":"jenny","source":{"name":"King James Bible (1611), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/10"},"rights":"pd","pd":"King James Version, 1611; public domain in the United States."},{"id":"cath-egypt-out-of-egypt","title":"Out of Egypt Have I Called My Son","by":"King James Version, Matthew 2:13 to 15","year":1611,"trad":["oriental"],"denom":["coptic"],"type":"scripture","occasion":["home","comfort"],"text":"And when they were departed, behold, the angel of the Lord appeareth to Joseph in a dream, saying, Arise, and take the young child and his mother, and flee into Egypt, and be thou there until I bring thee word: for Herod will seek the young child to destroy him.\nWhen he arose, he took the young child and his mother by night, and departed into Egypt:\nAnd was there until the death of Herod: that it might be fulfilled which was spoken of the Lord by the prophet, saying, Out of Egypt have I called my son.","note":"The Holy Family's flight into Egypt, dear to Coptic Christians, who keep the feast of its arrival each year; a comfort for families far from home.","voice":"brian","source":{"name":"King James Bible (1611), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/10"},"rights":"pd","pd":"King James Version, 1611; public domain in the United States."},{"id":"cath-blessed-be-egypt","title":"Blessed Be Egypt My People (Isaiah 19)","by":"King James Version, Isaiah 19:19, 25","year":1611,"trad":["oriental"],"denom":["coptic","syriac"],"type":"scripture","occasion":["blessing","hope"],"text":"In that day shall there be an altar to the Lord in the midst of the land of Egypt, and a pillar at the border thereof to the Lord.\n\nWhom the Lord of hosts shall bless, saying, Blessed be Egypt my people, and Assyria the work of my hands, and Israel mine inheritance.","note":"A blessing over Egypt and Assyria that Coptic and Syriac Christians hold close as their own.","voice":"jenny","source":{"name":"King James Bible (1611), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/10"},"rights":"pd","pd":"King James Version, 1611; public domain in the United States."},{"id":"cath-philip-and-the-ethiopian","title":"Philip and the Ethiopian (Acts 8)","by":"King James Version, Acts 8:35 to 39","year":1611,"trad":["oriental","christian"],"denom":["ethiopian"],"type":"scripture","occasion":["blessing","celebration"],"text":"Then Philip opened his mouth, and began at the same scripture, and preached unto him Jesus.\nAnd as they went on their way, they came unto a certain water: and the eunuch said, See, here is water; what doth hinder me to be baptized?\nAnd Philip said, If thou believest with all thine heart, thou mayest. And he answered and said, I believe that Jesus Christ is the Son of God.\nAnd he commanded the chariot to stand still: and they went down both into the water, both Philip and the eunuch; and he baptized him.\nAnd when they were come up out of the water, the Spirit of the Lord caught away Philip, that the eunuch saw him no more: and he went on his way rejoicing.","note":"The baptism of the Ethiopian official, honored by Ethiopian Christians as the first light of the Gospel in their land.","voice":"brian","source":{"name":"King James Bible (1611), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/10"},"rights":"pd","pd":"King James Version, 1611; public domain in the United States."},{"id":"cath-blessing-coptic","title":"A Blessing in the Coptic Spirit","by":"Grow With Grounded","year":2026,"trad":["oriental"],"denom":["coptic"],"type":"blessing","occasion":["blessing","comfort"],"text":"Blessed be the land that sheltered the Holy Family.\nMay the One who walked the roads of Egypt as a child walk beside you now.\nMay the faith of the martyrs make you brave,\nand the songs of the desert fathers and mothers keep your heart quiet and strong.\nPeace be with you.","note":"Grounded words to honor the Coptic Orthodox Church, used beside the family's own Agpeya prayers.","voice":"jenny","source":{"name":"Grow With Grounded, written for the Grounded Readings Library (2026)","url":""},"rights":"grounded","pd":"Grounded's own words."},{"id":"cath-blessing-armenian","title":"A Blessing in the Armenian Spirit","by":"Grow With Grounded","year":2026,"trad":["oriental"],"denom":["armenian"],"type":"blessing","occasion":["blessing","grief","hope"],"text":"You come from a people who kept the faith on mountain and in exile.\nMay the light of Saint Gregory the Illuminator shine on you.\nMay the cross carved in stone remind you that love outlasts every sorrow.\nMay the memory of your ancestors be a blessing, and your children's children sing.","note":"Grounded words to honor the Armenian Apostolic Church, used beside the family's own prayers and the priest's Hokehankist service.","voice":"brian","source":{"name":"Grow With Grounded, written for the Grounded Readings Library (2026)","url":""},"rights":"grounded","pd":"Grounded's own words."},{"id":"cath-blessing-ethiopian","title":"A Blessing in the Ethiopian Spirit","by":"Grow With Grounded","year":2026,"trad":["oriental"],"denom":["ethiopian","eritrean"],"type":"blessing","occasion":["blessing","celebration"],"text":"May you stretch out your hands to God, as your ancestors did.\nMay the light of the Meskel fire warm your home,\nand the long, patient prayers of your church hold you up.\nMay you rise each morning with gladness, and walk each day in peace.","note":"Grounded words to honor the Ethiopian and Eritrean Orthodox Tewahedo Churches.","voice":"jenny","source":{"name":"Grow With Grounded, written for the Grounded Readings Library (2026)","url":""},"rights":"grounded","pd":"Grounded's own words."},{"id":"cath-blessing-syriac","title":"A Blessing in the Syriac Spirit","by":"Grow With Grounded","year":2026,"trad":["oriental"],"denom":["syriac","malankara"],"type":"blessing","occasion":["blessing","peace"],"text":"Peace be with you, in the language Jesus spoke.\nMay the hymns of Saint Ephrem, the harp of the Spirit, sing in your heart.\nMay the light that rose in the East rise in you,\nand your home be a place where every guest is welcomed as Christ.","note":"Grounded words to honor the Syriac Orthodox and Malankara churches.","voice":"brian","source":{"name":"Grow With Grounded, written for the Grounded Readings Library (2026)","url":""},"rights":"grounded","pd":"Grounded's own words."}];
